/* السادس العلمي · الفصل الثاني · القطوع المخروطية — مولَّد من المصدر، لا تعدّله يدوياً */
(function(){
"use strict";
/* السادس العلمي · الفصل الثاني · القطوع المخروطية — مشاهد الرسم */
const sq=Math.sqrt, PI=Math.PI, abs=Math.abs;
const fr=(v,d=2)=>{ if(!isFinite(v)) return '—'; let r=Math.round(v*10**d)/10**d; if(Math.abs(r)<1e-9) r=0; return (r<0?'−':'')+String(Math.abs(r)); };
const T=(A,x,y,s,col='ink2',o={})=>A.lab(x,y,s,{fill:A.col[col]||col,w:o.w??700,size:o.size||13,anchor:o.anchor,halo:1});
const S={};

/* ---------- helpers ---------- */
const dot=(A,x,y,col='c',r=6)=>A.el('circle',{cx:A.X(x),cy:A.Y(y),r,fill:A.col[col]||col,stroke:A.col.surf,'stroke-width':2},A.G);
const seg=(A,x0,y0,x1,y1,col='muted',w=2,dash)=>A.el('path',{d:`M${A.X(x0)} ${A.Y(y0)}L${A.X(x1)} ${A.Y(y1)}`,stroke:A.col[col]||col,'stroke-width':w,'stroke-dasharray':dash,fill:'none'},A.G);
/* parametric curve; breaks the path where a point is missing (null) */
function pcurve(A,fn,t0,t1,col='f',w=2.8,n=240,dash){ let d='',pen=false;
  for(let i=0;i<=n;i++){ const p=fn(t0+(t1-t0)*i/n); if(!p||!isFinite(p[0])||!isFinite(p[1])){ pen=false; continue; }
    d+=(pen?'L':'M')+A.X(p[0]).toFixed(1)+' '+A.Y(p[1]).toFixed(1); pen=true; }
  A.el('path',{d,stroke:A.col[col]||col,'stroke-width':w,fill:'none','stroke-dasharray':dash,'stroke-linejoin':'round'},A.G); }
const vline=(A,x,col='tan',lab)=>{ seg(A,x,A.V.y0,x,A.V.y1,col,2,'7 5'); if(lab) T(A,A.X(x)+6,A.Y(A.V.y1)+16,lab,col,{anchor:'start',size:12}); };
const hline=(A,y,col='tan',lab)=>{ seg(A,A.V.x0,y,A.V.x1,y,col,2,'7 5'); if(lab) T(A,A.X(A.V.x1)-6,A.Y(y)-8,lab,col,{anchor:'end',size:12}); };
const ptl=(A,x,y,lab,col='c',dx=8,dy=-10,anchor='start')=>{ dot(A,x,y,col,5.5); T(A,A.X(x)+dx,A.Y(y)+dy,lab,col,{anchor,size:12.5}); };

/* ---------- 2−1 ---------- */
/* focus–directrix definition: points whose distance to F is e times their distance to D */
S.ecc={v:[-5,9,-5.5,5.5],eq:1,title:'القطع المخروطي: MF = e · MQ',hint:'e = 1 مكافئ ، e < 1 ناقص ، e > 1 زائد',
 sl:{min:.3,max:2,v:1,step:.01,play:1,speed:.12,lab:'الاختلاف المركزي e',fmt:v=>fr(v,2)},
 draw(A){ const e=A.p, d=2; vline(A,-d,'tan','الدليل D'); ptl(A,0,0,'F','c',8,18);
  pcurve(A,t=>{ const den=1-e*Math.cos(t); if(den<=.02) return null; const r=e*d/den; if(r>40) return null; return [r*Math.cos(t),r*Math.sin(t)]; },0.0001,2*PI-0.0001,'f',3,600);
  /* a sample point and its two distances */
  const t=2.2, r=e*d/(1-e*Math.cos(t)), mx=r*Math.cos(t), my=r*Math.sin(t);
  if(r<30){ seg(A,0,0,mx,my,'c',1.6,'4 4'); seg(A,mx,my,-d,my,'tan',1.6,'4 4'); dot(A,mx,my,'f',6); T(A,A.X(mx)-8,A.Y(my)-10,'M','f',{anchor:'end'});
    A.chips.push(['c','MF',fr(r,2)],['tan','MQ',fr(abs(mx+d),2)]); }
  A.chips.push(['f','النوع',abs(e-1)<.015?'مكافئ':e<1?'ناقص':'زائد']); }};

/* ---------- 2−2 ---------- */
/* parabola y² = 4px : every point is as far from the focus as from the directrix */
S.parab={v:[-4,7,-5.2,5.2],eq:1,title:'القطع المكافئ y² = 4px : MF = MQ',hint:'حرّك النقطة M على المنحني',
 sl:{min:-4.6,max:4.6,v:2.8,step:.01,play:1,speed:.25,lab:'موضع M',fmt:v=>''},
 draw(A){ const p=1.5, y=A.p, x=y*y/(4*p);
  vline(A,-p,'tan','x = −p'); pcurve(A,t=>[t*t/(4*p),t],-5.2,5.2,'f',3);
  ptl(A,p,0,'F(p , 0)','c',6,18); dot(A,0,0,'ink2',4);
  seg(A,x,y,p,0,'c',2,'5 4'); seg(A,x,y,-p,y,'tan',2,'5 4'); dot(A,-p,y,'tan',5); dot(A,x,y,'f',7);
  T(A,A.X(x)+8,A.Y(y)-10,'M','f',{anchor:'start'}); T(A,A.X(-p)-8,A.Y(y)-8,'Q','tan',{anchor:'end'});
  A.chips.push(['c','MF',fr(Math.hypot(x-p,y),2)],['tan','MQ',fr(x+p,2)],['f','M',`(${fr(x,2)} , ${fr(y,2)})`]); }};
/* the four standard parabolas with vertex at the origin (table p.57) */
const PO=[['x² = 4py','نحو الأعلى',0],['x² = −4py','نحو الأسفل',1],['y² = 4px','نحو اليمين',2],['y² = −4px','نحو اليسار',3]];
S.porient={v:[-5,5,-4.2,4.2],eq:1,title:'المعادلات القياسية الأربع (الرأس في نقطة الأصل)',hint:'المتغير المربّع يحدد المحور العمودي على المحور، وإشارة p تحدد الاتجاه',
 sl:{min:0,max:3,v:0,step:1,play:1,speed:.35,lab:'المعادلة',fmt:v=>PO[Math.round(v)][0]},
 draw(A){ const k=Math.round(A.p), p=1;
  const C=[t=>[t,t*t/(4*p)],t=>[t,-t*t/(4*p)],t=>[t*t/(4*p),t],t=>[-t*t/(4*p),t]][k];
  pcurve(A,C,-4.4,4.4,'f',3);
  const F=[[0,p],[0,-p],[p,0],[-p,0]][k]; ptl(A,F[0],F[1],'F','c',8,-8);
  if(k<2) hline(A,k?p:-p,'tan',k?'y = p':'y = −p'); else vline(A,k===2?-p:p,'tan',k===2?'x = −p':'x = p');
  A.chips.push(['f','المعادلة',PO[k][0]],['c','البؤرة',['(0 , p)','(0 , −p)','(p , 0)','(−p , 0)'][k]],['tan','الفتحة',PO[k][1]]); }};

/* ---------- 2−3 ---------- */
/* translating the axes: the parabola x² = y slides so that its vertex moves from (0,0) to (h,k) = (−2,−4) (example 10) */
/* ---------- translation helpers: the centre (h , k) is dragged (scene.drag2), the slider animates the move from the origin ---------- */
const sgn=v=>v<0?'+ '+fr(-v,2):'− '+fr(v,2);
const sqT=(v,n)=>Math.abs(v)<1e-9?n+'²':`(${n} ${sgn(v)})²`;
const linT=(v,n)=>Math.abs(v)<1e-9?n:`${n} ${sgn(v)}`;
const moveTxt=(h,k)=>{ const H=Math.abs(h)<1e-9?'دون انسحاب أفقي':(h>0?'يميناً':'يساراً')+' بمقدار '+fr(Math.abs(h),2), K=Math.abs(k)<1e-9?'دون انسحاب رأسي':(k>0?'للأعلى':'للأسفل')+' بمقدار '+fr(Math.abs(k),2);
  return 'اسحب المركز إلى أي موضع · '+H+' ، '+K; };
function transVec(A,h,k){ if(Math.hypot(h,k)<.3) return; const f=A.col, X=A.X, Y=A.Y;
  seg(A,0,0,h,0,'chord',1.6,'4 4'); seg(A,h,0,h,k,'chord',1.6,'4 4');
  const x0=X(0),y0=Y(0),x1=X(h),y1=Y(k), L=Math.hypot(x1-x0,y1-y0), ux=(x1-x0)/L, uy=(y1-y0)/L, e=11, xe=x1-ux*10, ye=y1-uy*10;
  A.el('path',{d:`M${x0} ${y0}L${xe} ${ye}`,stroke:f.chord,'stroke-width':2.4,fill:'none'},A.G);
  A.el('path',{d:`M${xe+ux*2} ${ye+uy*2}L${xe-ux*e-uy*e*.55} ${ye-uy*e+ux*e*.55}L${xe-ux*e+uy*e*.55} ${ye-uy*e-ux*e*.55}Z`,fill:f.chord},A.G);
  if(Math.abs(h)>.5) T(A,(X(0)+X(h))/2,Y(0)+(k>=0?16:-8),'h = '+fr(h,2),'chord',{anchor:'middle',size:11.5});
  if(Math.abs(k)>.5) T(A,X(h)+(h>=0?8:-8),(Y(0)+Y(k))/2,'k = '+fr(k,2),'chord',{anchor:h>=0?'start':'end',size:11.5}); }
const grip=(A,h,k)=>{ A.el('circle',{cx:A.X(h),cy:A.Y(k),r:17,fill:A.col.f,opacity:.16}); A.el('circle',{cx:A.X(h),cy:A.Y(k),r:7.5,fill:A.col.f,stroke:A.col.surf,'stroke-width':2.5}); };

S.ptrans={v:[-8,8,-6.5,6.5],eq:1,title:'انسحاب المحاور: الرأس ينتقل إلى (h , k)',hint:'',
 modes:{lab:'فتحة القطع',opts:['للأعلى','للأسفل','لليمين','لليسار'],v:0},
 drag2:{x:-2,y:-4,snap:1,box:m=>[[-6,6,-5,3],[-6,6,-3,5],[-6,5,-5,5],[-5,6,-5,5]][m],full:1},
 sl:{min:0,max:1,v:1,step:.01,play:1,speed:.25,lab:'الانسحاب',fmt:v=>Math.round(v*100)+'%'},
 draw(A){ const t=A.p, h=A.q.x*t, k=A.q.y*t, p=.25, m=A.m, vert=m<2, s=m%2?-1:1;
  /* vertical: (x−h)² = ±4p(y−k) ; horizontal: (y−k)² = ±4p(x−h) — here 4p = 1 as in example 10 */
  const C=(h0,k0)=>u=>vert?[h0+u,k0+s*u*u/(4*p)]:[h0+s*u*u/(4*p),k0+u];
  pcurve(A,C(0,0),-2.6,2.6,'muted',1.3,120,'2 6');
  transVec(A,h,k);
  pcurve(A,C(h,k),-3.4,3.4,'f',3);
  if(vert){ hline(A,k-s*p,'tan','الدليل'); seg(A,h,A.V.y0,h,A.V.y1,'c',1.3,'3 5'); ptl(A,h,k+s*p,'F','c',10,s>0?-6:16); }
  else { vline(A,h-s*p,'tan','الدليل'); seg(A,A.V.x0,k,A.V.x1,k,'c',1.3,'3 5'); ptl(A,h+s*p,k,'F','c',s>0?6:-6,-10,s>0?'start':'end'); }
  grip(A,h,k); T(A,A.X(h)+(vert?12:-12),A.Y(k)+(vert?(s>0?18:-12):18),'(h , k)','f',{anchor:vert?'start':'end',size:12.5});
  const lin=(v,n)=>s>0?linT(v,n):(Math.abs(v)<1e-9?'−'+n:`−(${linT(v,n)})`);
  const eq=vert?`${sqT(h,'x')} = ${lin(k,'y')}`:`${sqT(k,'y')} = ${lin(h,'x')}`;
  const F=vert?[h,k+s*p]:[h+s*p,k];
  A.chips.push(['f','المعادلة',eq],['f','الرأس',`(${fr(h,2)} , ${fr(k,2)})`],['c','البؤرة',`(${fr(F[0],2)} , ${fr(F[1],2)})`],['tan','الدليل',(vert?'y = ':'x = ')+fr(vert?k-s*p:h-s*p,2)]);
  A.hint=moveTxt(h,k); }};

/* ---------- 2−4 ---------- */
function ellipse(A,h,k,a,b,horiz,col='f',w=3){ pcurve(A,t=>horiz?[h+a*Math.cos(t),k+b*Math.sin(t)]:[h+b*Math.cos(t),k+a*Math.sin(t)],0,2*PI,col,w,200); }
/* string definition: PF₁ + PF₂ = 2a for every point (example 11 (1): x²/25 + y²/16 = 1) */
S.ell={v:[-6.5,6.5,-5,5],eq:1,title:'القطع الناقص: PF₁ + PF₂ = 2a',hint:'مجموع البعدين ثابت مهما تحركت P',
 sl:{min:0,max:6.283,v:1.1,step:.01,play:1,speed:.15,lab:'موضع P',fmt:v=>''},
 draw(A){ const a=5,b=4,c=3,t=A.p, x=a*Math.cos(t), y=b*Math.sin(t);
  ellipse(A,0,0,a,b,1);
  seg(A,c,0,x,y,'c',2.4); seg(A,-c,0,x,y,'tan',2.4);
  ptl(A,c,0,'F₁','c',6,18); ptl(A,-c,0,'F₂','tan',-6,18,'end'); dot(A,x,y,'f',7); T(A,A.X(x)+8,A.Y(y)-10,'P','f',{anchor:'start'});
  [[a,0,'V₁'],[-a,0,'V₂']].forEach(([px,py,l])=>{ dot(A,px,py,'ink2',4); T(A,A.X(px),A.Y(py)-10,l,'ink2',{anchor:'middle',size:11.5}); });
  const d1=Math.hypot(x-c,y), d2=Math.hypot(x+c,y);
  A.chips.push(['c','PF₁',fr(d1,2)],['tan','PF₂',fr(d2,2)],['f','المجموع 2a',fr(d1+d2,2)]); }};
/* the two standard ellipses with centre at the origin */
const EO=[[5,4,1,'x²/25 + y²/16 = 1 (مثال 11)'],[6,4,0,'x²/16 + y²/36 = 1 (مثال 13)']];
S.eorient={v:[-7.5,7.5,-6.6,6.6],eq:1,title:'البؤرتان على المحور الأكبر دائماً',hint:'المقام الأكبر هو a² ، والمتغير تحته يحدد محور البؤرتين',
 sl:{min:0,max:1,v:0,step:1,play:1,speed:.3,lab:'المعادلة',fmt:v=>EO[Math.round(v)][3]},
 draw(A){ const [a,b,hz]=EO[Math.round(A.p)], c=sq(a*a-b*b);
  ellipse(A,0,0,a,b,hz);
  const P=hz?[[c,0,'F₁','c'],[-c,0,'F₂','c'],[a,0,'V₁','f'],[-a,0,'V₂','f'],[0,b,'M₁','tan'],[0,-b,'M₂','tan']]:[[0,c,'F₁','c'],[0,-c,'F₂','c'],[0,a,'V₁','f'],[0,-a,'V₂','f'],[b,0,'M₁','tan'],[-b,0,'M₂','tan']];
  P.forEach(([x,y,l,cl])=>ptl(A,x,y,l,cl,6,-8));
  A.chips.push(['f','a',fr(a,2)],['tan','b',fr(b,2)],['c','c = √(a² − b²)',fr(c,3)],['muted','e = c/a',fr(c/a,3)]); }};

/* ---------- 2−5 ---------- */
/* translating an ellipse: centre (h , k); example 18 : (x − 2)²/9 + (y − 1)²/25 = 1 */
S.etrans={v:[-10,10,-9,9],eq:1,title:'انسحاب القطع الناقص: المركز (h , k)',hint:'',
 modes:{lab:'المحور الكبير',opts:['أفقي','رأسي'],v:1},
 drag2:{x:2,y:1,snap:1,box:m=>m?[-6,6,-3,3]:[-4,4,-5,5],full:1},
 sl:{min:0,max:1,v:1,step:.01,play:1,speed:.25,lab:'الانسحاب',fmt:v=>Math.round(v*100)+'%'},
 draw(A){ const t=A.p, h=A.q.x*t, k=A.q.y*t, a=5, b=3, c=4, hz=!A.m;
  ellipse(A,0,0,a,b,hz,'muted',1.3);
  seg(A,h,A.V.y0,h,A.V.y1,'c',1.3,'3 5'); seg(A,A.V.x0,k,A.V.x1,k,'tan',1.3,'3 5');
  transVec(A,h,k);
  ellipse(A,h,k,a,b,hz);
  if(hz){ ptl(A,h+c,k,'F₁','c',4,-10); ptl(A,h-c,k,'F₂','c',-4,-10,'end'); ptl(A,h+a,k,'V₁','f',6,18); ptl(A,h-a,k,'V₂','f',-6,18,'end'); }
  else { ptl(A,h,k+c,'F₁','c'); ptl(A,h,k-c,'F₂','c'); ptl(A,h,k+a,'V₁','f'); ptl(A,h,k-a,'V₂','f'); }
  grip(A,h,k); T(A,A.X(h)-12,A.Y(k)-12,'(h , k)','f',{anchor:'end',size:12.5});
  const F1=hz?[h+c,k]:[h,k+c], F2=hz?[h-c,k]:[h,k-c];
  A.chips.push(['f','المعادلة',`${sqT(h,'x')}/${hz?25:9} + ${sqT(k,'y')}/${hz?9:25} = 1`],['ink2','المركز',`(${fr(h,2)} , ${fr(k,2)})`],['c','F₁',`(${fr(F1[0],1)} , ${fr(F1[1],1)})`],['c','F₂',`(${fr(F2[0],1)} , ${fr(F2[1],1)})`]);
  A.hint=moveTxt(h,k); }};

/* ---------- 2−6 ---------- */
function hyper(A,h,k,a,b,horiz,col='f',w=3){ const R=2.6;
  [1,-1].forEach(s=>pcurve(A,t=>horiz?[h+s*a*Math.cosh(t),k+b*Math.sinh(t)]:[h+b*Math.sinh(t),k+s*a*Math.cosh(t)],-R,R,col,w,160)); }
function asym(A,h,k,a,b,horiz){ const m=horiz?b/a:a/b, L=40;
  seg(A,h-L,k-m*L,h+L,k+m*L,'muted',1.3,'6 5'); seg(A,h-L,k+m*L,h+L,k-m*L,'muted',1.3,'6 5');
  const [rx,ry]=horiz?[a,b]:[b,a]; A.el('path',{d:`M${A.X(h-rx)} ${A.Y(k-ry)}H${A.X(h+rx)}V${A.Y(k+ry)}H${A.X(h-rx)}Z`,stroke:A.col.muted,'stroke-width':1.2,fill:'none'},A.G); }
/* difference definition: |PF₁ − PF₂| = 2a (example 19 : x²/64 − y²/36 = 1) */
S.hyp={v:[-16,16,-12,12],eq:1,title:'القطع الزائد: |PF₁ − PF₂| = 2a',hint:'الفرق المطلق ثابت على الفرعين كليهما',
 sl:{min:-4,max:4,v:1.3,step:.01,play:1,speed:.3,lab:'موضع P',fmt:v=>''},
 draw(A){ const a=8,b=6,c=10, t=A.p, s=t<0?-1:1, u=Math.abs(t)-2, x=s*a*Math.cosh(u), y=b*Math.sinh(u);
  asym(A,0,0,a,b,1); hyper(A,0,0,a,b,1);
  seg(A,c,0,x,y,'c',2.2); seg(A,-c,0,x,y,'tan',2.2);
  ptl(A,c,0,'F₁','c',6,18); ptl(A,-c,0,'F₂','tan',-6,18,'end'); ptl(A,a,0,'V₁','f',4,-10); ptl(A,-a,0,'V₂','f',-4,-10,'end');
  dot(A,x,y,'f',7); T(A,A.X(x)+8,A.Y(y)-10,'P','f',{anchor:'start'});
  const d1=Math.hypot(x-c,y), d2=Math.hypot(x+c,y);
  A.chips.push(['c','PF₁',fr(d1,2)],['tan','PF₂',fr(d2,2)],['f','|PF₁ − PF₂|',fr(abs(d1-d2),2)]); }};
/* the two standard hyperbolas and the rectangle–asymptote construction */
const HO=[[3,sq(27),1,'x²/9 − y²/27 = 1 (مثال 20)'],[2,2,0,'y²/4 − x²/4 = 1 (مثال 21)']];
S.horient={v:[-9,9,-7.5,7.5],eq:1,title:'رسم الزائد: المستطيل والقطران (المستقيمان المحاذيان)',hint:'الحد الموجب يحدد محور البؤرتين، و c² = a² + b²',
 sl:{min:0,max:1,v:0,step:1,play:1,speed:.3,lab:'المعادلة',fmt:v=>HO[Math.round(v)][3]},
 draw(A){ const [a,b,hz]=HO[Math.round(A.p)], c=sq(a*a+b*b);
  asym(A,0,0,a,b,hz); hyper(A,0,0,a,b,hz);
  const P=hz?[[c,0,'F₁','c'],[-c,0,'F₂','c'],[a,0,'V₁','f'],[-a,0,'V₂','f']]:[[0,c,'F₁','c'],[0,-c,'F₂','c'],[0,a,'V₁','f'],[0,-a,'V₂','f']];
  P.forEach(([x,y,l,cl])=>ptl(A,x,y,l,cl,6,-8));
  A.chips.push(['f','a',fr(a,2)],['tan','b',fr(b,2)],['c','c = √(a² + b²)',fr(c,3)],['muted','e = c/a',fr(c/a,3)]); }};

/* ---------- 2−7 ---------- */
/* translating a hyperbola: example 22 : (x + 2)²/9 − (y − 1)²/4 = 1 , centre (−2 , 1) */
S.htrans={v:[-13,13,-8.5,8.5],eq:1,title:'انسحاب القطع الزائد: المركز (h , k)',hint:'',
 modes:{lab:'المحور الحقيقي',opts:['أفقي','رأسي'],v:0},
 drag2:{x:-2,y:1,snap:1,box:m=>m?[-8,8,-4,4]:[-6,6,-5,5],full:1},
 sl:{min:0,max:1,v:1,step:.01,play:1,speed:.25,lab:'الانسحاب',fmt:v=>Math.round(v*100)+'%'},
 draw(A){ const t=A.p, h=A.q.x*t, k=A.q.y*t, a=3, b=2, c=sq(13), hz=!A.m;
  hyper(A,0,0,a,b,hz,'muted',1.2);
  asym(A,h,k,a,b,hz); transVec(A,h,k); hyper(A,h,k,a,b,hz);
  if(hz){ ptl(A,h+c,k,'F₁','c',4,-10); ptl(A,h-c,k,'F₂','c',-4,-10,'end'); ptl(A,h+a,k,'V₁','f',4,18); ptl(A,h-a,k,'V₂','f',-4,18,'end'); }
  else { ptl(A,h,k+c,'F₁','c',10,4); ptl(A,h,k-c,'F₂','c',10,4); ptl(A,h,k+a,'V₁','f',-10,4,'end'); ptl(A,h,k-a,'V₂','f',-10,4,'end'); }
  grip(A,h,k); T(A,A.X(h)-10,A.Y(k)-14,'(h , k)','f',{anchor:'end',size:12.5});
  const F1=hz?[h+c,k]:[h,k+c], F2=hz?[h-c,k]:[h,k-c];
  const eq=hz?`${sqT(h,'x')}/9 − ${sqT(k,'y')}/4 = 1`:`${sqT(k,'y')}/9 − ${sqT(h,'x')}/4 = 1`;
  A.chips.push(['f','المعادلة',eq],['ink2','المركز',`(${fr(h,2)} , ${fr(k,2)})`],['c','F₁',`(${fr(F1[0],2)} , ${fr(F1[1],2)})`],['c','F₂',`(${fr(F2[0],2)} , ${fr(F2[1],2)})`]);
  A.hint=moveTxt(h,k); }};

window.BOOK=Object.assign({"id": "g12c2", "grade": "السادس العلمي", "chapter": "الفصل الثاني", "title": "القطوع المخروطية", "classic": "", "desc": "تعريف القطع المخروطي والاختلاف المركزي، القطع المكافئ والناقص والزائد: معادلاتها القياسية، البؤر والرؤوس والدليل، رسمها، وانسحاب محاورها."},{S,F:typeof F!=='undefined'?F:{},G:typeof GEN!=='undefined'?GEN:{},src:"=== parab | 2−1 , 2−2 | القطع المخروطي والقطع المكافئ | 48–59 | تعريف القطع المخروطي بالبؤرة والدليل والاختلاف المركزي، ثم القطع المكافئ الذي رأسه نقطة الأصل: معادلاته الأربع وبؤرته ودليله.\n--- @discover اكتشف: نسبة ثابتة ترسم المنحني\n>>> ecc .act\nk: الفصل الثاني · القطوع المخروطية · Conic Sections\nh1: بؤرة ودليل ونسبة ثابتة\nlead: نقطة ثابتة $F$ (البؤرة) ومستقيم ثابت $D$ (الدليل). كل نقطة $M$ نسبة بعدها عن $F$ إلى بعدها عن $D$ تساوي عدداً ثابتاً $\\cf{e}$ تقع على قطع مخروطي.\np: **حرّك e** : عند $e=1$ مكافئ، وعند $e<1$ ناقص (مغلق)، وعند $e>1$ زائد (فرعان).\n>>>\nask: ما قيمة الاختلاف المركزي للقطع المكافئ؟\no: $0$\no*: $1$\no: $2$\nwhy: في المكافئ كل نقطة بعدها عن البؤرة يساوي بعدها عن الدليل، فالنسبة $e=1$ .\n--- @understand افهم: التعريف والمعادلة القياسية\n>>> ecc .book\nk: [2] · القطوع المخروطية واهمية دراستها · ص 49–50\np: لنبحث اولاً عن وجود مثل هذه القطوع في الكون والطبيعة سوف ترى الكواكب والنجوم تتحرك على مدارات اهليلجية . (اي المدارات تشبه القطع الناقص) وفي الذرة والالكترون يلاحظ المختصون بان الالكترونات تدور حول النواة على مدارات اهليلجية ايضاً ، ومن التطبيقات الاخرى للقطوع المخروطية استخدامها في انتشار الصوت حيث نلاحظها في الات تكبير الصوت الحديثة وكذلك تستخدم في انتشار الضوء كما في ضوء السيارة فهو مجسم مكافئ وضع في بؤرته مصباحاً . عندما ينطلق شعاع ضوئي من المصباح ينعكس هذا الشعاع على السطح المجسم وبصورة افقية . وكذلك جميع الاشعة المنطلقة من المصباح مما يؤدي الى انارة الطريق امام السيارة .\np: نلاحظ مما سبق مدى اهمية القطوع المخروطية التي اصبحت دراستها محل اهتمام الرياضيين والفلكيين وعلماء الفضاء والميكانيكيين وكان للحضارة العربية الاسلامية دور هام في مواصلة هذه الدراسات بعد اطلاعهم على اعمال الرياضيين الاغريق امثال مينشم ، وابولنيوس ، وبابوس . ومن العلماء العرب الذين اهتموا بالقطوع المخروطية ثابت بن قرة وابو جعفر الخازن ، وابا سهل الكوهي ، وابن الهيثم وغيرهم كثيرون .\n>>> ecc .book\np: سبق وتعرفنا في الصف الخامس العلمي على كيفية تولد القطوع المخروطية : الدائرة – القطع المكافئ – القطع الناقص – القطع الزائد . حيث يتم الحصول على هذه القطوع هندسياً وكالاتي :\nlaw: اذا قطع سطح المخروط الدائري القائم\n| بمستوٍ عمودي على محور المخروط الدائري القائم ولا يحوي رأس المخروط الدائري القائم فان المقطع يمثل شكلاً هندسياً يسمى دائرة (**Circle**) .\n| بمستوٍ موازٍ لأحد مولداته فأن المقطع يمثل شكلاً هندسياً يسمى القطع المكافئ (**Parabola**) .\n| بمستوٍ غير موازٍ لقاعدته ولا يوازي احد مولداته فأن القطع يمثل شكلاً هندسياً يسمى القطع الناقص (**Ellipse**) .\n| بمستوٍ يوازي محور المخروط الدائري القائم ويقطع مولدين من مولدات المخروط الدائري القائم فان المقطع يمثل شكلاً هندسياً يسمى القطع الزائد (**Hyperbola**) .\n>>> ecc .book\nk: [2−1] · القطع المخروطي · ص 51\np: لتكن $(x_1,y_1)$ نقطة ثابتة في المستوي وليكن $ax+by+c=0$ مستقيماً ثابتاً في المستوي نفسه ، عندئذ مجموعة كل النقاط التي نسبة بُعد كل منها عن النقطة $(x_1,y_1)$ الى بعدها عن المستقيم $ax+by+c=0$ تساوي عدداً ثابتاً $(e)$ تكون شكل هندسي يسمى بالقطع المخروطي .\np: مما سبق نلاحظ ان لكل قطع مخروطي (ما عدا الدائرة) ثلاثة مفاهيم اساسية يتعين بها هي :\nlaw:\n| **1−** النقطة الثابتة $(x_1,y_1)$ تسمى بؤرة القطع المخروطي \"**Focus**\" .\n| **2−** المستقيم الثابت $ax+by+c=0$ يسمى دليل القطع المخروطي \"**Directrix**\" .\n| **3−** النسبة $(e)$ تسمى بالاختلاف المركزي \"**Eccentricity**\" .\nnote: **ملاحظة:**\n| في القطع المكافئ (**Parabola**) : $e=1$\n| في القطع الناقص (**Ellipse**) : $e<1\\ ,\\ 0<e<1$\n| في القطع الزائد (**Hyperbola**) : $e>1$\n>>> ecc .book\nk: [2−1−1] · المعادلة العامة للقطع المخروطي · ص 51–52\np: من تعريف القطع المخروطي نستنتج المعادلة العامة وذلك كما يأتي :\np: لتكن $(x,y)$ نقطة على القطع المخروطي ، عندئذ المسافة بين $(x,y)$ والبؤرة $(x_1,y_1)$ هي : $\\sqrt{(x-x_1)^2+(y-y_1)^2}$\np: والبعد بين $(x,y)$ والدليل $ax+by+c=0$ هي : $\\dfrac{|ax+by+c|}{\\sqrt{a^2+b^2}}$\np: وبموجب تعريف القطع المخروطي فان النسبة بين هاتين المسافتين تساوي $(e)$ اي ان\n$$\\frac{\\sqrt{(x-x_1)^2+(y-y_1)^2}}{\\dfrac{|ax+by+c|}{\\sqrt{a^2+b^2}}}=e\n$$\\Rightarrow\\sqrt{(x-x_1)^2+(y-y_1)^2}=e\\cdot\\frac{|ax+by+c|}{\\sqrt{a^2+b^2}}\nlaw: وبتربيع الطرفين نحصل على معادلة القطع المخروطي العامة وهي معادلة من الدرجة الثانية\n| $$(x-x_1)^2+(y-y_1)^2=e^2\\cdot\\frac{(ax+by+c)^2}{a^2+b^2}\nnote: **ملاحظة :** سنطبق هذه المعادلة على القطع المكافئ لأنه قد تم تعريف الدليل\n>>> parab .book\nk: [2−2] · القطع المكافئ · Parabola · ص 52\np: القطع المكافئ هو مجموعة النقط $M(x,y)$ في المستوي والتي يكون بُعد كل منها عن نقطة ثابتة $F(p,0)$ تسمى البؤرة حيث $p>0$ مساوياً دائماً لبعدها عن مستقيم معلوم \"$D$\" يسمى الدليل لا يحوي البؤرة .\np: اي ان $MF=MQ$ لاحظ الشكل (2−2) : وتسمى النقطة \"$O$\" برأس القطع المكافئ \"**Vertex**\" ويسمى المستقيم $(x)$ المار بالبؤرة والعمود على الدليل بمحور القطع المكافئ . حيث لاحظ ان $\\dfrac{MF}{MQ}=e=1$\n>>> parab .book\nk: [2−2−1] · ص 53–54\nh2: معادلة القطع المكافئ الذي بؤرته تنتمي لمحور السينات (x-axis) والرأس في نقطة الأصل\np: في المستوي الديكارتي المتعامد المحورين وبناءاً على تعريف القطع المكافئ يمكن ايجاد معادلة القطع المكافئ في ابسط صورة ممكنة وكما يأتي :\np: لتكن النقطة $F(p,0)$ هي بؤرة القطع المكافئ والمستقيم $D$ هو دليل القطع المكافئ ، والنقطة $Q(-p,y)$ نقطة على الدليل حيث $\\overline{MQ}$ عمودي على المستقيم $D$ ، والنقطة $M(x,y)$ من نقط منحني القطع المكافئ والرأس في نقطة الاصل $(0,0)$ . كما في الشكل (2−3) (A) . من تعريف القطع المكافئ .\n$$MF=MQ\n$$\\sqrt{(x-p)^2+(y-0)^2}=\\sqrt{(x+p)^2+(y-y)^2}\np: بتربيع الطرفين\n$$x^2-2px+p^2+y^2=x^2+2xp+p^2\nlaw: (المعادلة القياسية للقطع المكافئ الذي رأسه نقطة الاصل وبؤرته تنتمي لمحور السينات)\n| $$y^2=4px\\ ,\\quad\\forall p>0\n| ومعادلة الدليل $x=-p$\n>>> porient .book\nk: [2−2−2] · ص 57\nh2: معادلة القطع المكافئ الذي بؤرته تنتمي لمحور الصادات (y-axis) والرأس في نقطة الأصل\np: في المستوي الديكارتي المتعامد المحورين لتكن النقطة $F(0,p)$ هي بؤرة القطع المكافئ ، والمستقيم $D$ دليل القطع المكافئ والنقطة $Q(x,-p)$ هي نقطة تقاطع العمود المرسوم من $M$ على الدليل ، والنقطة $M(x,y)$ من نقط منحني القطع المكافئ والرأس في نقطة الاصل $(0,0)$ كما في الشكل (2−7) A وبناءاً على تعريف القطع المكافئ فان $MF=MQ$\n$$\\Rightarrow\\sqrt{(x-0)^2+(y-p)^2}=\\sqrt{(x-x)^2+(y+p)^2}\n$$\\Rightarrow x^2+(y-p)^2=(y+p)^2\n$$x^2+y^2-2py+p^2=y^2+2py+p^2\n$$x^2=4py\\ ,\\quad\\forall p>0\np: المعادلة القياسية للقطع المكافئ\np: الجدول الاتي يمثل المعادلة القياسية للقطع المكافئ الذي رأسه في نقطة الاصل حيث $p>0$\ntbh: المعادلة | البؤرة | الدليل | المحور | فتحة القطع\ntbl: $x^2=4py$ | $(0,p)$ | $y=-p$ | y-axis | نحو الاعلى\ntbl: $x^2=-4py$ | $(0,-p)$ | $y=p$ | y-axis | نحو الاسفل\ntbl: $y^2=4px$ | $(p,0)$ | $x=-p$ | x-axis | نحو اليمين\ntbl: $y^2=-4px$ | $(-p,0)$ | $x=p$ | x-axis | نحو اليسار\n--- @learn تعلّم الحل: نقارن بالمعادلة القياسية\n>>> porient .book\nk: فكرة الحل في هذا الدرس\nh2: المقارنة بالجدول\nxp: فكرة الحل في هذا الدرس\n| **1) نرتّب** المعادلة: المتغير المربّع وحده في طرف (نقسم على معامله).\n| **2) نقارن** بالجدول: $y^2$ ⇐ المحور السيني، $x^2$ ⇐ المحور الصادي، والإشارة تحدد الفتحة.\n| **3) نجد** $4p$ ثم $p>0$ ، ومنها البؤرة والدليل.\n| **عكسياً:** من البؤرة أو الدليل نجد $p$ والاتجاه ثم نكتب المعادلة.\n| **فحص:** البؤرة والدليل على جهتين مختلفتين من الرأس، والبعد بينهما $2p$ .\n>>> porient .book\nk: مثال 1 · ص 54\nh2: البؤرة والدليل\np: جد البؤرة ومعادلة دليل القطع المكافئ $y^2=-8x$\nlet: المعطيات\n| المعادلة ; المعطاة ; $y^2=-8x$\n| المتغير المربّع ; $y$ ; المحور السيني\n| الإشارة ; سالبة ; الفتحة نحو اليسار\nmain: [المعادلة القياسية] الفتحة نحو اليسار\n| $$y^2=-4px\\ ,\\quad F(-p,0)\\ ,\\quad x=p\n>>> porient #1 :: نقارن ونجد p\n$$y^2=-8x\np: بالمقارنة مع المعادلة القياسية $y^2=-4px$\n$$\\Rightarrow4p=8\\Rightarrow p=\\frac84=2>0\\qquad\\therefore\\ p=2\n>>> porient ! #2 :: البؤرة والدليل\n$$F(-p,0)=F(-2,0)\np: معادلة الدليل $x=p$\n$$\\therefore\\ x=2\nxp: فحص\n| البؤرة $(-2,0)$ يسار الرأس.\n| الدليل $x=2$ يمين الرأس.\n| البعد بينهما $4=2p$ ✓\n>>> porient .book\nk: مثال 2 · ص 55\nh2: المعادلة من البؤرة أو الدليل\np: جد معادلة القطع المكافئ اذا علم : **أ)** بؤرته $(3,0)$ والرأس نقطة الاصل . **ب)** معادلة الدليل $2x-6=0$ ورأسه نقطة الاصل .\nlet: المعطيات\n| أ ; البؤرة ; $(3,0)$\n| ب ; الدليل ; $2x-6=0$\n| الرأس ; نقطة الأصل ; $(0,0)$\nmain: [المعادلة القياسية] من الجدول\n| $$y^2=\\pm4px\n>>> porient #1 :: أ) من البؤرة\np: **الحل أ)**\n$$(p,0)=(3,0)\\Rightarrow p=3\np: (المعادلة القياسية)\n$$\\therefore\\ y^2=4px\n$$\\Rightarrow y^2=(4)(3)x=12x\\qquad y^2=12x\n>>> porient ! #2 :: ب) من الدليل\np: **ب)** من معادلة الدليل\n$$2x-6=0\\Rightarrow2x=6\\Rightarrow x=3\np: $\\therefore\\ p=3$ (بفضل التعريف) . بتطبيق المعادلة القياسية\n$$y^2=-4px\n$$y^2=(-4)(3)x=-12x\\Rightarrow y^2=-12x\nxp: لماذا الإشارة سالبة في (ب)؟\n| الدليل $x=3$ يمين الرأس، والبؤرة في الجهة المقابلة $(-3,0)$ ، فالفتحة نحو اليسار.\n>>> parab .book\nk: مثال 3 · ص 55–56\nh2: الرسم\np: جد بؤرة ومعادلة دليل القطع المكافئ $y^2=4x$ ثم أرسمه :\nlet: المعطيات\n| المعادلة ; المعطاة ; $y^2=4x$\n| الفتحة ; نحو اليمين ; $y^2=4px$\n| المطلوب ; البؤرة والدليل ; ثم الرسم\nmain: [المعادلة القياسية] الفتحة نحو اليمين\n| $$y^2=4px\\ ,\\quad F(p,0)\\ ,\\quad x=-p\n>>> parab #1 :: البؤرة والدليل\np: **الحل:** بالمقارنة مع معادلة القطع المكافئ :\n$$y^2=4px\\Rightarrow4p=4\\Rightarrow p=1\np: البؤرة $F(1,0)$ ، معادلة الدليل $x=-1$\n>>> parab ! #2 :: جدول القيم والرسم\n$$y^2=4x\\Rightarrow y=\\pm2\\sqrt x\ntbh: $x$ | $0$ | $1$ | $2$\ntbl: $y$ | $0$ | $\\pm2$ | $\\pm2\\sqrt2$\np: الشكل (2−5)\nxp: فحص بنقطة\n| النقطة $(1,2)$ :\n| بعدها عن البؤرة $(1,0)$ يساوي $2$\n| بعدها عن الدليل $x=-1$ يساوي $2$ ✓\n>>> parab .book\nk: مثال 4 · ص 56\nh2: باستخدام التعريف\np: باستخدام التعريف جد معادلة القطع المكافئ اذا علم ان بؤرته $(\\sqrt3,0)$ والرأس في نقطة الأصل .\nlet: المعطيات\n| $F$ ; البؤرة ; $(\\sqrt3,0)$\n| $D$ ; الدليل ; $x=-\\sqrt3$\n| المطلوب ; بالتعريف ; $MF=MQ$\nmain: [تعريف القطع المكافئ] البعدان متساويان\n| $$MF=MQ\n>>> parab #1 :: نكتب البعدين\np: **الحل:** البؤرة $F(\\sqrt3,0)$ ، ولتكن النقطة $M(x,y)$ من نقط منحني القطع المكافئ ، والنقطة $Q(-\\sqrt3,y)$ هي نقطة تقاطع العمود المرسوم من $M$ على الدليل $D$ ومن تعريف القطع المكافئ .\n$$\\sqrt{(x-\\sqrt3)^2+(y-0)^2}=\\sqrt{(x+\\sqrt3)^2+(y-y)^2}\n>>> parab ! #2 :: نربّع ونبسّط\np: (بتربيع الطرفين)\n$$(x-\\sqrt3)^2+y^2=(x+\\sqrt3)^2\n$$x^2-2\\sqrt3x+3+y^2=x^2+2\\sqrt3x+3\n$$y^2=4\\sqrt3x\np: (بالتبسيط) (معادلة القطع المكافئ) . الشكل (2−6)\nxp: فحص بالجدول\n| $p=\\sqrt3$ في $y^2=4px$ يعطي $y^2=4\\sqrt3x$ مباشرة ✓\n>>> porient .book\nk: مثال 5 · ص 58\nh2: نقسم أولاً\np: جد البؤرة ومعادلة دليل القطع المكافئ $3x^2-24y=0$ .\nlet: المعطيات\n| المعادلة ; المعطاة ; $3x^2-24y=0$\n| المتغير المربّع ; $x$ ; المحور الصادي\n| الخطوة الأولى ; نقسم على 3 ; $x^2=8y$\nmain: [المعادلة القياسية] الفتحة نحو الأعلى\n| $$x^2=4py\\ ,\\quad F(0,p)\\ ,\\quad y=-p\n>>> porient #1 :: نرتّب ونقارن\np: **الحل:** [ بقسمة طرفي المعادلة على $(3)$ ]\n$$3x^2-24y=0\\Rightarrow x^2=8y\np: بالمقارنة مع المعادلة القياسية للقطع المكافئ $x^2=4py$\n$$\\Rightarrow4p=8\\Rightarrow p=2\n>>> porient ! #2 :: البؤرة والدليل\np: ومن قيمة $p$ نجد\np: البؤرة $F(0,2)$ ، معادلة الدليل $y=-2$\nxp: فحص\n| النقطة $(4,2)$ على المنحني لأن $16=8\\times2$ :\n| بعدها عن $F(0,2)$ يساوي $4$\n| بعدها عن الدليل $y=-2$ يساوي $4$ ✓\n>>> porient .book\nk: مثال 6 · ص 58\nh2: المعادلة من البؤرة أو الدليل\np: جد معادلة القطع المكافئ اذا علم ان : **أ)** بؤرته $(0,5)$ ورأسه نقطة الاصل . **ب)** معادلة الدليل $y=7$ ورأسه نقطة الاصل .\nlet: المعطيات\n| أ ; البؤرة ; $(0,5)$\n| ب ; الدليل ; $y=7$\n| الرأس ; نقطة الأصل ; $(0,0)$\nmain: [المعادلة القياسية] المحور الصادي\n| $$x^2=\\pm4py\n>>> porient #1 :: الحل أ\n$$F(0,5)\\Rightarrow p=5\np: المعادلة القياسية $x^2=4py$\n$$x^2=20y\np: (معادلة القطع المكافئ)\n>>> porient ! #2 :: الحل ب\n$$y=7\\ ,\\quad p=7\np: (المعادلة القياسية) $x^2=-4py$\n$$x^2=-28y\nxp: لماذا −4py في (ب)؟\n| الدليل فوق الرأس ($y=7$) ، فالبؤرة تحته $(0,-7)$ والفتحة نحو الأسفل.\n>>> parab .book\nk: مثال 7 · ص 59\nh2: من نقطتين على المنحني\np: جد معادلة القطع المكافئ الذي يمر بالنقطتين $(2,4)$ ، $(2,-4)$ ورأسه نقطة الاصل .\nlet: المعطيات\n| النقطتان ; متناظرتان حول المحور السيني ; $(2,4)\\ ,\\ (2,-4)$\n| الرأس ; نقطة الأصل ; $(0,0)$\n| المطلوب ; $p$ ثم المعادلة ; $y^2=4px$\nmain: [المعادلة القياسية] نعوّض نقطة\n| $$y^2=4px\\ ,\\quad\\forall p>0\n>>> parab #1 :: نختار المعادلة\np: **الحل:** النقطتان متناظرتان حول المحور السيني . اذاً المعادلة القياسية $y^2=4px\\ ,\\ \\forall p>0$\n>>> parab ! #2 :: نعوّض النقطة\np: نعوض احدى النقطتين اللتين تحققان المعادلة القياسية ولتكن النقطة $(2,4)$\n$$16=(4)(p)(2)\n$$16=8p\\Rightarrow p=\\frac{16}{8}\\Rightarrow p=2\np: نعوض $p=2$ في المعادلة القياسية\n$$y^2=(4)(2)x\\Rightarrow y^2=8x\np: معادلة القطع المكافئ .\nxp: فحص\n| $(2,-4)$ : $16=8\\times2$ ✓ . والنقطتان على يمين المحور الصادي ($x=2>0$) ، فالفتحة نحو اليمين.\n>>> porient .book\nk: مثال 8 · ص 59\nh2: احتمالان\np: جد معادلة القطع المكافئ الذي رأسه نقطة الاصل ويمر دليل القطع المكافئ بالنقطة $(3,-5)$\nlet: المعطيات\n| الدليل ; يمر بالنقطة ; $(3,-5)$\n| الرأس ; نقطة الأصل ; $(0,0)$\n| المحور ; غير محدد ; احتمالان\nmain: [المعادلة القياسية] لكل محور احتمال\n| $$x^2=\\pm4py\\quad\\text{or}\\quad y^2=\\pm4px\n>>> porient #1 :: البؤرة على محور الصادات\np: **الحل:** يوجد احتمالين للمعادلة القياسية لعدم تحديد موقع البؤرة هما :\np: **اولاً : البؤرة تنتمي لمحور الصادات** : الدليل أفقي يمر بالنقطة، فمعادلته $y=-5$\n$$p=5\\ ,\\quad x^2=4py\\Rightarrow x^2=20y\n>>> porient ! #2 :: البؤرة على محور السينات\np: **ثانياً : البؤرة تنتمي لمحور السينات** : الدليل عمودي يمر بالنقطة، فمعادلته $x=3$\n$$p=3\\ ,\\quad y^2=-4px\\Rightarrow y^2=-12x\nxp: فحص\n| الحالة الأولى: الدليل $y=-5$ تحت الرأس، فالفتحة نحو الأعلى ✓\n| الحالة الثانية: الدليل $x=3$ يمين الرأس، فالفتحة نحو اليسار ✓\n--- @practice تدرّب: تمارين ص 65 (الرأس في نقطة الأصل)\n>>> porient .book\nk: تمارين · ص 65\nh2: دورك الآن\np: **1.** جد المعادلة للقطع المكافئ في كل مما يأتي ثم ارسم المنحني البياني لها . **أ−** البؤرة $(5,0)$ والرأس نقطة الاصل .\nxp: قالب الحل\n| **موقع البؤرة أو الدليل** ← **المحور والفتحة** من الجدول ← **$p$** (موجب دائماً) ← **المعادلة** ← **فحص:** البؤرة والدليل على جهتين مختلفتين من الرأس\nnote: التمرين 2 (c – f) معادلاته رأسها ليس في نقطة الأصل، فيأتي في درس [2−3] .\nself:\nsol: **الحل:**\n| let> $F$ ; البؤرة ; $(5,0)$\n| main> [المعادلة القياسية] الفتحة نحو اليمين\n| $$y^2=4px\n| $p=5\\Rightarrow y^2=20x$\n>>> porient .book\np: **ب−** البؤرة $(-4,0)$ والرأس نقطة الاصل .\nself:\nsol: **الحل:**\n| let> $F$ ; البؤرة ; $(-4,0)$\n| main> [المعادلة القياسية] الفتحة نحو اليسار\n| $$y^2=-4px\n| $p=4\\Rightarrow y^2=-16x$\n>>> porient .book\np: **ج−** البؤرة $(0,\\sqrt2)$ والرأس نقطة الاصل .\nself:\nsol: **الحل:**\n| let> $F$ ; البؤرة ; $(0,\\sqrt2)$\n| main> [المعادلة القياسية] الفتحة نحو الأعلى\n| $$x^2=4py\n| $p=\\sqrt2\\Rightarrow x^2=4\\sqrt2\\,y$\n>>> porient .book\np: **د−** معادلة دليل القطع المكافئ $4y-3=0$ والرأس نقطة الاصل .\nself:\nhint: الدليل $y=\\tfrac34$ فوق الرأس.\nsol: **الحل:**\n| let> $D$ ; الدليل ; $y=\\dfrac34$\n| main> [المعادلة القياسية] الفتحة نحو الأسفل\n| $$x^2=-4py\n| $p=\\dfrac34\\Rightarrow x^2=-3y$\n>>> porient .book\np: **2.** في كل مما يأتي جد البؤرة والرأس ومعادلتي المحور والدليل للقطع المكافئ: **a)** $x^2=4y$\nself:\nsol: **الحل:**\n| let> المعادلة ; القياسية ; $x^2=4py$\n| main> [المعادلة القياسية] الفتحة نحو الأعلى\n| $$4p=4\\Rightarrow p=1\n| البؤرة $(0,1)$ ، الرأس $(0,0)$\n| المحور $x=0$ ، الدليل $y=-1$\n>>> porient .book\np: **b)** $2x+16y^2=0$\nself:\nhint: $y^2=-\\dfrac{x}{8}$\nsol: **الحل:**\n| let> المعادلة ; بعد الترتيب ; $y^2=-\\dfrac18x$\n| main> [المعادلة القياسية] الفتحة نحو اليسار\n| $$4p=\\frac18\\Rightarrow p=\\frac{1}{32}\n| البؤرة $\\left(-\\dfrac{1}{32},0\\right)$ ، الرأس $(0,0)$\n| المحور $y=0$ ، الدليل $x=\\dfrac{1}{32}$\n>>> parab .book\np: **3.** جد معادلة القطع المكافئ الذي يمر بالنقطتين $(-5,2)$ ، $(-5,-2)$ والراس في نقطة الاصل .\nself:\nhint: النقطتان متناظرتان حول المحور السيني ويسار المحور الصادي.\nsol: **الحل:**\n| let> النقطتان ; متناظرتان حول محور السينات ; $x=-5<0$\n| main> [المعادلة القياسية] الفتحة نحو اليسار\n| $$y^2=-4px\n| نعوّض $(-5,2)$ : $4=-4p(-5)=20p\\Rightarrow p=\\dfrac15$\n| $y^2=-\\dfrac45x$\n>>> porient .book\np: **4.** اذا كان دليل القطع المكافئ يمر بالنقطة $(-3,4)$ والرأس في نقطة الاصل جد معادلته علماً ان بؤرته تنتمي لأحد المحورين .\nself:\nhint: كما في المثال 8 : احتمالان.\nsol: **الحل:**\n| let> الدليل ; يمر بالنقطة ; $(-3,4)$\n| main> [المعادلة القياسية] احتمالان\n| $$x^2=\\pm4py\\quad\\text{or}\\quad y^2=\\pm4px\n| البؤرة على محور الصادات: الدليل $y=4$ ⇐ $p=4$ ⇐ $x^2=-16y$\n| البؤرة على محور السينات: الدليل $x=-3$ ⇐ $p=3$ ⇐ $y^2=12x$\n>>> porient .book\np: **5.** قطع مكافئ معادلته $Ax^2+8y=0$ يمر بالنقطة $(1,2)$ جد قيمة $A$ ثم جد بؤرته ودليله و أرسم القطع .\nprac: -16 ; قيمة A\nhint: عوّض النقطة: $A(1)^2+8(2)=0$ .\nsol: **الحل:**\n| let> النقطة ; على المنحني ; $(1,2)$\n| main> [المعادلة القياسية] بعد إيجاد $A$\n| $$x^2=4py\n| $A+16=0\\Rightarrow A=-16$\n| $-16x^2+8y=0\\Rightarrow x^2=\\dfrac12y\\Rightarrow4p=\\dfrac12\\Rightarrow p=\\dfrac18$\n| البؤرة $\\left(0,\\dfrac18\\right)$ ، الدليل $y=-\\dfrac18$\n>>> parab .book\np: **6.** باستخدام التعريف . جد معادلة القطع المكافئ **أ−** البؤرة $(7,0)$ والرأس نقطة الاصل .\nself:\nhint: كما في المثال 4 : $MF=MQ$ مع $Q(-7,y)$ .\nsol: **الحل:**\n| let> $F , D$ ; البؤرة والدليل ; $(7,0)\\ ,\\ x=-7$\n| main> [تعريف القطع المكافئ] البعدان متساويان\n| $$MF=MQ\n| $\\sqrt{(x-7)^2+y^2}=\\sqrt{(x+7)^2}$\n| $x^2-14x+49+y^2=x^2+14x+49\\Rightarrow y^2=28x$\n>>> parab .book\np: **ب−** معادلة الدليل $y=\\sqrt3$ ، والرأس نقطة الاصل .\nself:\nhint: البؤرة $(0,-\\sqrt3)$ و $Q(x,\\sqrt3)$ .\nsol: **الحل:**\n| let> $F , D$ ; البؤرة والدليل ; $(0,-\\sqrt3)\\ ,\\ y=\\sqrt3$\n| main> [تعريف القطع المكافئ] البعدان متساويان\n| $$MF=MQ\n| $\\sqrt{x^2+(y+\\sqrt3)^2}=\\sqrt{(y-\\sqrt3)^2}$\n| $x^2+y^2+2\\sqrt3y+3=y^2-2\\sqrt3y+3\\Rightarrow x^2=-4\\sqrt3\\,y$\n--- @check تحقّق\n>>> porient .enr\nk: تقويم قصير · ليس من الكتاب\np: ما بؤرة القطع المكافئ $x^2=-12y$ ؟\nask: اختر:\no: $(0,3)$\no*: $(0,-3)$\no: $(-3,0)$\nwhy: $x^2=-4py$ مع $4p=12\\Rightarrow p=3$ ، والفتحة نحو الأسفل فالبؤرة $(0,-3)$ .\n>>> ecc .enr\np: قطع مخروطي اختلافه المركزي $e=\\tfrac12$ . ما نوعه؟\nask: اختر:\no: مكافئ\no*: ناقص\no: زائد\nwhy: $0<e<1$ ⇐ قطع ناقص.\n>>> parab .summary\nh2: الخلاصة\n- القطع المخروطي: $\\dfrac{MF}{MQ}=e$ ؛ مكافئ $e=1$ ، ناقص $0<e<1$ ، زائد $e>1$ .\n- المكافئ (الرأس في الأصل): $y^2=\\pm4px$ أو $x^2=\\pm4py$ ، $p>0$ .\n- البؤرة على بعد $p$ من الرأس داخل الفتحة، والدليل على بعد $p$ في الجهة المقابلة.\n\n=== ptrans | 2−3 | انسحاب المحاور للقطع المكافئ | 60–65 | الرأس (h , k) : المعادلات (y − k)² = ±4p(x − h) و (x − h)² = ±4p(y − k) ، والبؤرة والدليل والمحور تنسحب مع الرأس.\n--- @discover اكتشف: القطع نفسه في مكان آخر\n>>> ptrans .act\nk: [2−3] · إنسحاب المحاور للقطع المكافئ\nh1: نحرّك القطع ولا نغيّر شكله\nlead: عندما ينتقل الرأس من $(0,0)$ إلى $\\cf{(h , k)}$ يبقى $p$ كما هو، وتنتقل البؤرة والدليل والمحور معه.\np: **حرّك الانسحاب** أو **اسحب المركز** إلى أي موضع لترى كل حالات h و k ، والمعادلة تتغير معه. هذا القطع $y=x^2+4x$ من المثال 10 ، ورأسه $(-2,-4)$ .\n>>>\nask: القطع $x^2=4py$ انسحب بحيث صار رأسه $(3,1)$ . ما معادلته؟\no: $(x+3)^2=4p(y+1)$\no*: $(x-3)^2=4p(y-1)$\no: $(x-1)^2=4p(y-3)$\nwhy: نستبدل $x$ بـ $x-h$ و $y$ بـ $y-k$ حيث $(h,k)=(3,1)$ .\n--- @understand افهم: المعادلات الأربع بعد الانسحاب\n>>> ptrans .book\nk: [2−3−1] · ص 60\nh2: المعادلة القياسية للقطع المكافئ الذي محوره يوازي أحد المحورين الأحداثيين ورأسه النقطة (h , k)\np: في البنود السابقة تعرفنا على المعادلتين القياسيتين للقطع المكافئ وهما :\n$$y^2=4px\\ \\ldots(1)\\qquad x^2=4py\\ \\ldots(2)\np: **المعادلة الاولى :** هي معادلة قطع مكافئ بؤرته تنتمي لمحور السينات ورأسه نقطة الاصل $(0,0)$ .\np: **المعادلة الثانية :** معادلة قطع مكافئ بؤرته تنتمي لمحور الصادات ورأسه نقطة الاصل $(0,0)$ .\np: فاذا كان الرأس هو النقطة $\\overline{O}(h,k)$ فان المعادلتين القياسيتين هما :\n$$(y-k)^2=4p(x-h)\\ \\ldots(3)\n$$(x-h)^2=4p(y-k)\\ \\ldots(4)\n>>> ptrans .book\nk: ص 60–61\np: **المعادلة الثالثة :** تمثل المعادلة القياسية للقطع المكافئ الذي رأسه النقطة $\\overline{O}(h,k)$ ومحوره يوازي محور السينات . لاحظ في الشكل (2−8) الانسحاب لمكونات القطع المكافئ .\nlaw: الانسحاب لمكوّنات القطع (المحور يوازي محور السينات)\n| انسحاب $O(0,0)$ ← $\\overline{O}(h,k)$\n| انسحاب $F(p,0)$ ← $\\overline{F}(p+h,k)$\n| انسحاب $x=-p$ ← $x=-p+h$\n| معادلة المحور $y=k$\np: حيث $(p)$ في المعادلة (3) ، (4) هو البعد البؤري للقطع المكافئ ويساوي المسافة بين الرأس $\\overline{O}$ والبؤرة $\\overline{F}$ ويساوي البعد بين الرأس ومعادلة الدليل اي ان : $p=|Q-h|$\np: ويمكن ان تكون فتحة القطع المكافئ بالاتجاه السالب لمحور السينات كما في الشكل (2−9) :\nlaw:\n| $$(y-k)^2=-4p(x-h)\n| البؤرة $(Q,k)=(h-p,k)$\n| معادلة الدليل $x=p+h$\n| معادلة المحور $y=k$\nnote: في البند [2−3] (انسحاب المحاور) سنكتفي فقط في ايجاد بؤرة ورأس القطع المكافئ ومعادلة الدليل ومعادلة المحور .\n>>> ptrans .book\nk: ص 63\np: **المعادلة الرابعة :** تمثل المعادلة القياسية للقطع المكافئ راسه النقطة $(h,k)$ ومحوره يوازي المحور الصادي . لاحظ الانسحاب لمكونات القطع المكافئ . كما في الشكل (2−10) .\nlaw: الانسحاب لمكوّنات القطع (المحور يوازي محور الصادات)\n| انسحاب $O(0,0)$ ← $\\overline{O}(h,k)$ الراس بعد الانسحاب\n| انسحاب $F(0,p)$ ← $\\overline{F}(h,Q)$ البؤرة بعد الانسحاب ، $Q=p+k$\n| $p=|Q-k|$ (البعد البؤري)\n| معادلة المحور $x=h$ ، معادلة الدليل $y=k-p$\nlaw:\n| $$(x-h)^2=-4p(y-k)\n| البؤرة $(h,k-p)$\n| معادلة الدليل $y=k+p$\n| معادلة المحور $x=h$\n--- @learn تعلّم الحل: نكمل المربع ثم نقارن\n>>> ptrans .book\nk: فكرة الحل في هذا الدرس\nh2: من المعادلة إلى الرأس والبؤرة\nxp: فكرة الحل في هذا الدرس\n| **1) نكمل المربع** للمتغير المربّع، ونجعل الطرف الآخر بالصورة $4p(\\ldots)$ .\n| **2) نقرأ** $h$ و $k$ بإشارتين معاكستين لما داخل القوسين.\n| **3) نجد** $p$ من $4p$ ، والإشارة تحدد الفتحة.\n| **4) ننقل** مكوّنات الجدول: البؤرة على بعد $p$ من الرأس داخل الفتحة، والدليل على بعد $p$ في الجهة المقابلة.\n| **فحص:** نفك المعادلة الناتجة فنعود إلى المعادلة المعطاة.\n>>> ptrans .book\nk: مثال 9 · ص 62\nh2: المحور يوازي محور السينات\np: من معادلة القطع المكافئ $(y+1)^2=4(x-2)$ عين الرأس ، البؤرة ، معادلة المحور ، معادلة الدليل .\nlet: المعطيات\n| المعادلة ; المعطاة ; $(y+1)^2=4(x-2)$\n| المتغير المربّع ; $y$ ; المحور يوازي محور السينات\n| الإشارة ; موجبة ; الفتحة نحو اليمين\nmain: [المعادلة الثالثة] الرأس $(h,k)$\n| $$(y-k)^2=4p(x-h)\n>>> ptrans #1 :: الرأس و p\np: **الحل:** بالمقارنة مع المعادلة القياسية للقطع المكافئ .\n$$(y+1)^2=4(x-2)\n$$(y-k)^2=4p(x-h)\n$$\\Rightarrow h=2\\ ,\\quad k=-1\np: (الرأس)\n$$\\therefore\\ (h,k)=(2,-1)\n$$4p=4\\Rightarrow p=1\n>>> ptrans ! #2 :: البؤرة والمحور والدليل\np: (البؤرة)\n$$\\therefore\\ F(p+h,k)=F(1+2,-1)=F(3,-1)\np: معادلة المحور $y=k$\n$$\\therefore\\ y=-1\np: معادلة الدليل\n$$x=-p+h=-1+2=1\\Rightarrow x=1\nxp: فحص\n| البؤرة $(3,-1)$ يمين الرأس $(2,-1)$ بمقدار $p=1$ .\n| الدليل $x=1$ يسار الرأس بالمقدار نفسه ✓\n>>> ptrans .book\nk: مثال 10 · ص 64\nh2: نكمل المربع\np: ناقش القطع المكافئ : $y=x^2+4x$\nlet: المعطيات\n| المعادلة ; المعطاة ; $y=x^2+4x$\n| الخطوة الأولى ; نكمل المربع ; نضيف 4\n| المطلوب ; الرأس والبؤرة والدليل ; $(h,k)\\ ,\\ p$\nmain: [المعادلة الرابعة] الرأس $(h,k)$\n| $$(x-h)^2=4p(y-k)\n>>> ptrans #1 :: إكمال المربع\np: **الحل:** نضيف 4 الى طرفي المعادلة حتى نضع حدود $x$ في شكل مربع كامل ، فنكتب :\n$$y+4=x^2+4x+4\n$$y+4=(x+2)^2\np: هذه المعادلة من الشكل : $(x-h)^2=4p(y-k)$\n>>> ptrans #2 :: الرأس و p\np: حيث\n$$h=-2\\ ,\\quad k=-4\np: الرأس $(-2,-4)$\n$$4p=1\\ ,\\quad p=\\frac14\n>>> ptrans ! #3 :: البؤرة والدليل\np: هذا القطع المكافئ مفتوح الى الاعلى لان من اجل قيم $x$ الحقيقية ولقيم $y\\ge-4$ وراسه $v(-2,-4)$ تقع البؤرة على بعد $\\tfrac14$ وحدة من رأس القطع ونحو الاعلى ، اي عند $F\\left(-2,-3\\tfrac34\\right)$ وان الدليل موازٍ للمحور $x$ ويبعد $4\\tfrac14$ وحدة من المحور $x$ . ومعادلته هي $y=-4\\tfrac14$ .\nxp: فحص\n| البؤرة: $k+p=-4+\\tfrac14=-3\\tfrac34$ ✓\n| الدليل: $k-p=-4-\\tfrac14=-4\\tfrac14$ ✓\n| وفك المعادلة: $(x+2)^2-4=x^2+4x$ ✓\n--- @practice تدرّب: تمارين ص 65 (رأس ليس في نقطة الأصل)\n>>> ptrans .book\nk: تمارين · 2 · ص 65\nh2: دورك الآن\np: **2.** في كل مما يأتي جد البؤرة والرأس ومعادلتي المحور والدليل للقطع المكافئ: **c)** $y^2=-4(x-2)$\nxp: قالب الحل\n| **نكمل المربع** ← **نقارن** بإحدى المعادلات الأربع ← **الرأس** $(h,k)$ ← **$p$** ← **البؤرة والدليل والمحور** ← **فحص** بفك المعادلة\nself:\nsol: **الحل:**\n| let> المعادلة ; القياسية ; $(y-k)^2=-4p(x-h)$\n| main> [الفتحة نحو اليسار] الرأس $(h,k)$\n| $$h=2\\ ,\\ k=0\\ ,\\ 4p=4\\Rightarrow p=1\n| الرأس $(2,0)$\n| البؤرة $(h-p,k)=(1,0)$\n| المحور $y=0$\n| الدليل $x=p+h=3$\n>>> ptrans .book\np: **d)** $(x-1)^2=8(y-1)$\nself:\nsol: **الحل:**\n| let> المعادلة ; القياسية ; $(x-h)^2=4p(y-k)$\n| main> [الفتحة نحو الأعلى] الرأس $(h,k)$\n| $$h=1\\ ,\\ k=1\\ ,\\ 4p=8\\Rightarrow p=2\n| الرأس $(1,1)$\n| البؤرة $(h,k+p)=(1,3)$\n| المحور $x=1$\n| الدليل $y=k-p=-1$\n>>> ptrans .book\np: **e)** $y^2+4y+2x=-6$\nself:\nhint: أكمل مربع $y$ : أضف 4 للطرفين.\nsol: **الحل:**\n| let> المعادلة ; بعد إكمال المربع ; $(y+2)^2=-2(x+1)$\n| main> [الفتحة نحو اليسار] الرأس $(h,k)$\n| $$h=-1\\ ,\\ k=-2\\ ,\\ 4p=2\\Rightarrow p=\\frac12\n| $y^2+4y+4=-2x-6+4=-2x-2$\n| الرأس $(-1,-2)$\n| البؤرة $\\left(-\\dfrac32,-2\\right)$\n| المحور $y=-2$\n| الدليل $x=p+h=-\\dfrac12$\n>>> ptrans .book\np: **f)** $x^2+6x-y=0$\nself:\nhint: أكمل مربع $x$ : أضف 9 للطرفين.\nsol: **الحل:**\n| let> المعادلة ; بعد إكمال المربع ; $(x+3)^2=y+9$\n| main> [الفتحة نحو الأعلى] الرأس $(h,k)$\n| $$h=-3\\ ,\\ k=-9\\ ,\\ 4p=1\\Rightarrow p=\\frac14\n| الرأس $(-3,-9)$\n| البؤرة $\\left(-3,-\\dfrac{35}{4}\\right)$\n| المحور $x=-3$\n| الدليل $y=k-p=-\\dfrac{37}{4}$\n--- @check تحقّق\n>>> ptrans .enr\nk: تقويم قصير · ليس من الكتاب\np: ما رأس القطع $(x+5)^2=12(y-2)$ ؟\nask: اختر:\no: $(5,-2)$\no*: $(-5,2)$\no: $(2,-5)$\nwhy: $(x-h)^2=4p(y-k)$ مع $x-h=x+5\\Rightarrow h=-5$ و $y-k=y-2\\Rightarrow k=2$ .\n>>> ptrans .enr\np: في القطع $(y-3)^2=-8(x-1)$ ، ما معادلة الدليل؟\nask: اختر:\no*: $x=3$\no: $x=-1$\no: $y=3$\nwhy: $4p=8\\Rightarrow p=2$ والفتحة نحو اليسار، فالدليل يمين الرأس: $x=h+p=1+2=3$ .\n>>> ptrans .summary\nh2: الخلاصة\n- الرأس $(h,k)$ : $(y-k)^2=\\pm4p(x-h)$ أو $(x-h)^2=\\pm4p(y-k)$ .\n- نكمل المربع، ونقرأ $h , k$ بإشارة معاكسة لما داخل القوس.\n- البؤرة والدليل والمحور تنسحب مع الرأس بالمقدار نفسه، و $p$ لا يتغير.\n\n=== ellipse | 2−4 | القطع الناقص | 66–79 | المركز في نقطة الأصل: x²/a² + y²/b² = 1 أو x²/b² + y²/a² = 1 ، مع c² = a² − b² ، والاختلاف المركزي e = c/a < 1 ، والمساحة والمحيط.\n--- @discover اكتشف: خيط مثبّت بدبوسين\n>>> ell .act\nk: [2−4] · القطع الناقص · Ellipse\nh1: مجموع بعدين ثابت\nlead: ثبّت طرفي خيط طوله $\\cf{2a}$ في نقطتين $F_1 , F_2$ وشدّه بقلم: يرسم القلم قطعاً ناقصاً.\np: **حرّك P** : الطولان يتغيران ومجموعهما يبقى $10$ .\n>>>\nask: نقطة على القطع بعدها عن إحدى البؤرتين $4$ ، و $2a=10$ . ما بعدها عن البؤرة الأخرى؟\no: $4$\no*: $6$\no: $14$\nwhy: $PF_1+PF_2=2a$ ⇐ $4+PF_2=10$ ⇐ $PF_2=6$ .\n--- @understand افهم: التعريف والمعادلتان والخصائص\n>>> ell .book\nk: [2−4] · ص 66\nlaw: تعريف [2−4−1]\n| القطع الناقص مجموعة من النقط في المستوي التي يكون مجموع بعديها عن نقطتين ثابتتين (البؤرتان) عدد ثابت .\nh2: [2−4−2] قطع ناقص بؤرتاه على محور السينات ومركزه نقطة الاصل\np: كما في الشكل (2−13) بؤرتا القطع الناقص هما $F_1(c,0)\\ ,\\ F_2(-c,0)$ والعدد الثابت هو $2a$ ، $a>0\\ ,\\ c>0$\np: تسمى النقطة التي تقع في منتصف القطعة المستقيمة الواصلة بين البؤرتين بمركز القطع الناقص (**Center**) ، ويسمى المستقيم المار بالبؤرتين بالمحور البؤري (**Focal axis**) ويقطع القطع الناقص في نقطتين تسميان رأسا القطع وتسمى قطعة المستقيم الواصلة بين الرأسين بالمحور الكبير (**Major axis**) وطولها $(2a)$ ايضاً ويساوي مجموع بعدي اي نقطة $P(x,y)$ من نقاط القطع الناقص عن البؤرتين اي ان :\n$$PF_1+PF_2=2a\np: وتسمى القطعة المستقيمة الواصلة بين نقطتي تقاطع المستقيم العمود على المحور الكبير من مركز القطع الناقص مع القطع الناقص بالمحور الصغير (**Minor axis**) وطولها $(2b)$ حيث $b>0$ ونهايتاه تسميان القطبين .\n>>> ell .book\nk: [2−4−3] · ص 67–68\nh2: معادلة القطع الناقص الذي بؤرتاه على محور السينات ومركزه نقطة الاصل\np: لاحظ الشكل (2−14) $\\because\\ PF_1+PF_2=2a$\n$$\\Rightarrow\\sqrt{(x-c)^2+(y-0)^2}+\\sqrt{(x+c)^2+(y-0)^2}=2a\n$$\\Rightarrow\\sqrt{(x-c)^2+y^2}=2a-\\sqrt{(x+c)^2+y^2}\np: (بتربيع طرفي المعادلة)\n$$\\Rightarrow(x-c)^2+y^2=4a^2-4a\\sqrt{(x+c)^2+y^2}+(x+c)^2+y^2\n$$\\Rightarrow4a\\sqrt{(x+c)^2+y^2}=4a^2+4cx\np: (بقسمة طرفي المعادلة على 4) (بتربيع طرفي المعادلة)\n$$\\Rightarrow a\\sqrt{(x+c)^2+y^2}=a^2+cx\n$$a^2\\left[x^2+2cx+c^2+y^2\\right]=a^4+2a^2cx+c^2x^2\np: بالتبسيط\n$$a^2x^2-c^2x^2+a^2y^2=a^4-a^2c^2\n$$x^2(a^2-c^2)+a^2y^2=a^2(a^2-c^2)\\ \\ldots(1)\np: بما ان $a>c$ دائماً فان $a^2-c^2>0$ وبفرض ان $b^2=a^2-c^2$ حيث $b>0$\n$$\\Rightarrow b^2=a^2-c^2\\ \\ldots(2)\np: نعوض 2 في 1 ، بقسمة طرفي المعادلة على $a^2b^2$\nlaw: تمثل المعادلة القياسية للقطع الناقص الذي بؤرتاه على محور السينات ومركزه نقطة الاصل\n| $$\\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1\n| وتسمى النسبة $\\dfrac ca$ بالاختلاف المركزي . أي ان $e=\\dfrac ca$ ويكون دائماً اقل من الواحد .\n>>> eorient .book\nk: [2−4−3] · ص 68–69\nh2: معادلة القطع الناقص الذي مركزه نقطة الاصل والبؤرتان تنتميان لمحور الصادات\np: لاحظ الشكل (2−15) بنفس خطوات الاشتقاق السابق لمعادلة القطع الناقص الذي بؤرتاه على محور السينات ومركزه نقطة الاصل وباستخدام التعريف نحصل على المعادلة : $\\dfrac{x^2}{b^2}+\\dfrac{y^2}{a^2}=1$ حيث البؤرتان على محور الصادات والمركز في نقطة الاصل . نلخص ما سبق بالآتي :\ntbh: | بؤرتاه على محور السينات | بؤرتاه على محور الصادات\ntbl: المعادلة | $\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1$ | $\\dfrac{x^2}{b^2}+\\dfrac{y^2}{a^2}=1$\ntbl: البؤرتان | $F_1(c,0)\\ ,\\ F_2(-c,0)$ | $F_1(0,c)\\ ,\\ F_2(0,-c)$\ntbl: الرأسان | $V_1(a,0)\\ ,\\ V_2(-a,0)$ | $V_1(0,a)\\ ,\\ V_2(0,-a)$\nlaw: في الحالتين\n| **4)** $c=\\sqrt{a^2-b^2}$ **5)** $a>c\\ ,\\ a>b$\n| **6)** طول المحور الكبير $=2a$ **7)** طول المحور الصغير $=2b$ **8)** المسافة بين البؤرتين $=2c$\n| **9)** مساحة منطقة القطع الناقص ويرمز لها $A$ (**Area**) : $A=ab\\pi$\n| **10)** محيط القطع الناقص ويرمز له $P$ (**Perimeter**) : $P=2\\pi\\sqrt{\\dfrac{a^2+b^2}{2}}\\ ,\\ \\pi=\\dfrac{22}{7}$\n| **11)** \"$e$\" الاختلاف المركزي ويكون دائماً اقل من الواحد $(e<1)$ : $e=\\dfrac ca=\\dfrac{\\sqrt{a^2-b^2}}{a}$\nxp: عن صيغة المحيط\n| صيغة المحيط هذه تقريبية (لا توجد صيغة بسيطة مضبوطة لمحيط القطع الناقص)، وهي المعتمدة في الكتاب.\n>>> ell .book\nk: [2−4−5] · Graph The Ellipse · ص 74\nh2: طريقة رسم القطع الناقص\np: لتكن $\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1$ معادلة قطع ناقص بؤرتاه تنتميان لمحور السينات ولرسم هذا القطع :\nlaw: خطوات الرسم\n| **1.** نعين النقطتين $V_1(a,0)\\ ,\\ V_2(-a,0)$\n| **2.** نعين النقطتين $M_1(0,b)\\ ,\\ M_2(0,-b)$\n| **3.** نصل بين النقاط الاربعة $V_1M_1V_2M_2$ على الترتيب بمنحني متصل .\n| **4.** نعين البؤرتين $F_1(c,0)\\ ,\\ F_2(-c,0)$\n--- @learn تعلّم الحل: المقام الأكبر هو a²\n>>> eorient .book\nk: فكرة الحل في هذا الدرس\nh2: أربع خطوات\nxp: فكرة الحل في هذا الدرس\n| **1) نجعل** الطرف الأيمن $1$ (نقسم على العدد الثابت).\n| **2) المقام الأكبر** هو $a^2$ ، والمتغير الذي تحته يحدد محور البؤرتين.\n| **3) نجد** $c$ من $c^2=a^2-b^2$ .\n| **4) نكتب** البؤرتين والرأسين والقطبين وأطوال المحاور و $e=\\tfrac ca$ .\n| **عكسياً:** من المعطيات نجد اثنين من $a , b , c$ ثم الثالث من $c^2=a^2-b^2$ .\n| **فحص:** $a>b$ و $a>c$ و $e<1$ .\n>>> eorient .book\nk: مثال 11 · ص 69–70\nh2: من المعادلة إلى العناصر\np: في كل مما يأتي جد طول كل من المحورين واحداثي كل من البؤرتين والرأسين والاختلاف المركزي . **1)** $\\dfrac{x^2}{25}+\\dfrac{y^2}{16}=1$ **2)** $4x^2+3y^2=\\dfrac43$\nlet: المعطيات\n| 1 ; المعادلة ; $\\dfrac{x^2}{25}+\\dfrac{y^2}{16}=1$\n| 2 ; المعادلة ; $4x^2+3y^2=\\dfrac43$\n| المطلوب ; المحوران والبؤرتان والرأسان ; $2a\\ ,\\ 2b\\ ,\\ e$\nmain: [القطع الناقص] المقام الأكبر هو $a^2$\n| $$c^2=a^2-b^2\\ ,\\quad e=\\frac ca\n>>> eorient #1 :: الحل 1: المحوران و c\np: **الحل (1)** بالمقارنة مع المعادلة القياسية $\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1$ حيث $a>b$ .\n$$\\Rightarrow a^2=25\\Rightarrow a=5\\Rightarrow2a=10\np: طول المحور الكبير ، وحدة\n$$b^2=16\\Rightarrow b=4\\Rightarrow2b=8\np: طول المحور الصغير ، وحدة\n$$c=\\sqrt{a^2-b^2}=\\sqrt{25-16}=\\sqrt9=3\n>>> eorient #2 :: الحل 1: البؤرتان والرأسان و e\n$$\\therefore\\ F_1(3,0)\\ ,\\ F_2(-3,0)\np: البؤرتان\n$$V_1(5,0)\\ ,\\ V_2(-5,0)\np: الرأسان\n$$e=\\frac ca=\\frac35<1\np: (الاختلاف المركزي)\n>>> eorient #3 :: الحل 2: نجعل الطرف الأيمن 1\np: **الحل (2)** بضرب طرفي المعادلة بـ $\\dfrac34$\n$$4x^2+3y^2=\\frac43\\Rightarrow3x^2+\\frac{9y^2}{4}=1\n$$\\frac{x^2}{\\frac13}+\\frac{y^2}{\\frac49}=1\n$$\\Rightarrow a^2=\\frac49\\Rightarrow a=\\frac23\\Rightarrow2a=\\frac43\np: طول المحور الكبير ، وحدة\n$$b^2=\\frac13\\Rightarrow b=\\frac{1}{\\sqrt3}\\Rightarrow2b=\\frac{2}{\\sqrt3}\np: طول المحور الصغير ، وحدة\n>>> eorient ! #4 :: الحل 2: البؤرتان والرأسان و e\n$$c=\\sqrt{a^2-b^2}\\Rightarrow c=\\sqrt{\\frac49-\\frac13}=\\sqrt{\\frac19}=\\frac13\np: البؤرتان $F_1\\left(0,\\tfrac13\\right)\\ ,\\ F_2\\left(0,-\\tfrac13\\right)$\np: الرأسان $V_1\\left(0,\\tfrac23\\right)\\ ,\\ V_2\\left(0,-\\tfrac23\\right)$\n$$\\therefore\\ e=\\frac ca=\\frac{\\frac13}{\\frac23}=\\frac12<1\np: (الاختلاف المركزي)\nxp: لماذا البؤرتان على محور الصادات في (2)؟\n| المقام الأكبر $\\tfrac49>\\tfrac13$ تحت $y^2$ ، فالمحور الكبير على محور الصادات.\n>>> eorient .book\nk: مثال 12 · ص 71\nh2: من البؤرتين والرأسين\np: جد معادلة القطع الناقص الذي بؤرتاه $F_1(3,0)\\ ,\\ F_2(-3,0)$ ورأساه النقطتان $V_1(5,0)\\ ,\\ V_2(-5,0)$ ومركزه نقطة الاصل .\nlet: المعطيات\n| $c$ ; من البؤرتين ; $3$\n| $a$ ; من الرأسين ; $5$\n| المطلوب ; المعادلة ; $\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1$\nmain: [القطع الناقص] نجد $b^2$\n| $$c^2=a^2-b^2\n>>> eorient #1 :: c و a\np: **الحل:** البؤرتان والرأسان يقعان على محور السينات والمركز في نقطة الاصل :\n$$\\therefore\\ \\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1\n$$\\Rightarrow c=3\\Rightarrow c^2=9\\qquad\\Rightarrow a=5\\Rightarrow a^2=25\n>>> eorient ! #2 :: b² والمعادلة\n$$\\Rightarrow c^2=a^2-b^2\\Rightarrow b^2=a^2-c^2=25-9=16\n$$\\frac{x^2}{25}+\\frac{y^2}{16}=1\np: معادلة القطع الناقص\nxp: فحص\n| $a=5>c=3$ و $a=5>b=4$ ✓ . وهي معادلة الفقرة (1) من المثال 11 نفسها.\n>>> eorient .book\nk: مثال 13 · ص 71\nh2: المساحة والمحيط\np: جد معادلة القطع الناقص الذي مركزه نقطة الاصل وينطبق محوراه على المحورين الاحداثيين ويقطع من محور السينات جزءاً طوله 8 وحدات ومن محور الصادات جزءاً طوله 12 وحدة ، ثم جد المسافة بين البؤرتين ومساحة منطقته ومحيطه .\nlet: المعطيات\n| على محور السينات ; الجزء المقطوع ; $2b=8$\n| على محور الصادات ; الأطول ; $2a=12$\n| المطلوب ; المعادلة والمساحة والمحيط ; $2c\\ ,\\ A\\ ,\\ P$\nmain: [المساحة والمحيط] $\\pi=\\dfrac{22}{7}$\n| $$A=ab\\pi\\ ,\\quad P=2\\pi\\sqrt{\\frac{a^2+b^2}{2}}\n>>> eorient #1 :: المعادلة\n$$2b=8\\Rightarrow b=4\\Rightarrow b^2=16\n$$2a=12\\Rightarrow a=6\\Rightarrow a^2=36\n$$\\frac{x^2}{16}+\\frac{y^2}{36}=1\n>>> eorient #2 :: المسافة بين البؤرتين\n$$c=\\sqrt{a^2-b^2}=\\sqrt{36-16}=2\\sqrt5\n$$\\Rightarrow2c=4\\sqrt5\np: المسافة بين البؤرتين ، وحدة\n>>> eorient ! #3 :: المساحة والمحيط\np: مساحة منطقة القطع الناقص $A=ab\\pi$\n$$A=(6)(4)\\pi=24\\pi\np: (وحدة مربعة) ، $\\pi=\\dfrac{22}{7}$\np: محيط القطع الناقص $\\because\\ P=2\\pi\\sqrt{\\dfrac{a^2+b^2}{2}}$\n$$P=2\\pi\\sqrt{\\frac{36+16}{2}}=2\\pi\\sqrt{\\frac{52}{2}}=2\\pi\\sqrt{26}\np: وحدة\nxp: فحص\n| الجزء الأطول على محور الصادات، فالبؤرتان $(0,\\pm2\\sqrt5)$ والمقام الأكبر تحت $y^2$ ✓\n>>> eorient .book\nk: مثال 14 · ص 72\nh2: مجهول في المعادلة\np: لتكن $kx^2+4y^2=36$ معادلة قطع ناقص مركزه نقطة الاصل واحدى بؤرتيه $(\\sqrt3,0)$ جد قيمة $k\\in R$ .\nlet: المعطيات\n| المعادلة ; المعطاة ; $kx^2+4y^2=36$\n| البؤرة ; على محور السينات ; $(\\sqrt3,0)$\n| المطلوب ; القيمة ; $k$\nmain: [القطع الناقص] العلاقة بين $a , b , c$\n| $$c^2=a^2-b^2\n>>> eorient #1 :: نجعل الطرف الأيمن 1\n$$kx^2+4y^2=36\\quad[\\div36]\n$$\\frac{x^2}{\\frac{36}{k}}+\\frac{y^2}{9}=1\np: من البؤرة $(\\sqrt3,0)$\n$$\\Rightarrow c=\\sqrt3\\Rightarrow c^2=3\n>>> eorient ! #2 :: نعوّض ونجد k\np: وبالمقارنة مع المعادلة القياسية $\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1$\n$$\\Rightarrow a^2=\\frac{36}{k}\\ ,\\quad b^2=9\\ ,\\quad c^2=3\\ \\ldots(1)\n$$c^2=a^2-b^2\\ \\ldots(2)\np: بالتعويض عن (1) في (2)\n$$3=\\frac{36}{k}-9\\Rightarrow k=3\nxp: فحص\n| $k=3$ ⇐ $\\dfrac{x^2}{12}+\\dfrac{y^2}{9}=1$ ⇐ $c^2=12-9=3$ ✓\n>>> eorient .book\nk: مثال 15 · ص 72–73\nh2: معادلتان في a و b\np: جد معادلة القطع الناقص الذي مركزه في نقطة الاصل وبؤرتاه على محور السينات والمسافة بين البؤرتين (6) وحدات ، والفرق بين طولي المحورين يساوي (2) وحدة .\nlet: المعطيات\n| $2c$ ; المسافة بين البؤرتين ; $6$\n| $2a-2b$ ; الفرق بين المحورين ; $2$\n| المطلوب ; المعادلة ; $\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1$\nmain: [القطع الناقص] العلاقة بين $a , b , c$\n| $$c^2=a^2-b^2\n>>> eorient #1 :: c و a بدلالة b\n$$2c=6\\Rightarrow c=3\n$$2a-2b=2\\quad\\div2\n$$a-b=1\\Rightarrow a=1+b\\ \\ldots(1)\n>>> eorient ! #2 :: نعوّض\n$$\\because\\ c^2=a^2-b^2\np: بالتعويض\n$$\\therefore\\ 9=(1+b)^2-b^2\n$$9=1+2b+b^2-b^2\\Rightarrow9=1+2b\n$$b=4\\ \\ldots(2)\np: تعويض (2) في (1)\n$$a=1+4=5\\Rightarrow a^2=25\n$$\\frac{x^2}{25}+\\frac{y^2}{16}=1\np: معادلة القطع الناقص\nxp: فحص\n| $2a-2b=10-8=2$ ✓ و $2c=2\\sqrt{25-16}=6$ ✓\n>>> eorient .book\nk: مثال 16 · ص 73\nh2: بؤرة من قطع مكافئ\np: جد معادلة القطع الناقص الذي مركزه نقطة الاصل واحدى بؤرتيه بؤرة القطع المكافئ $y^2-12x=0$ ، وطول محوره الصغير يساوي (10) وحدات .\nlet: المعطيات\n| المكافئ ; معادلته ; $y^2=12x$\n| $2b$ ; المحور الصغير ; $10$\n| المطلوب ; معادلة الناقص ; $\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1$\nmain: [القطع الناقص] العلاقة بين $a , b , c$\n| $$c^2=a^2-b^2\n>>> eorient #1 :: بؤرة المكافئ\n$$y^2-12x=0\\Rightarrow y^2=12x\np: $y^2=4px$ (بالمقارنة مع المعادلة القياسية)\n$$4p=12\\Rightarrow p=3\np: بؤرتا القطع الناقص هما : $F_1(3,0)\\ ,\\ F_2(-3,0)$\n>>> eorient ! #2 :: a² والمعادلة\n$$\\Rightarrow c=3\\Rightarrow c^2=9\n$$2b=10\\Rightarrow b=5\\Rightarrow b^2=25\n$$\\because\\ c^2=a^2-25\\qquad\\therefore\\ 9=a^2-25\n$$a^2=34\n$$\\frac{x^2}{34}+\\frac{y^2}{25}=1\np: معادلة القطع الناقص\nxp: فحص\n| $a^2=34>b^2=25$ ، والمقام الأكبر تحت $x^2$ فالبؤرتان على محور السينات ✓\n>>> ell .book\nk: مثال 17 · ص 74\nh2: باستخدام التعريف\np: باستخدام التعريف ، جد معادلة القطع الناقص الذي بؤرتاه : $F_1(2,0)\\ ,\\ F_2(-2,0)$ والعدد الثابت $=6$\nlet: المعطيات\n| البؤرتان ; على محور السينات ; $(\\pm2,0)$\n| $2a$ ; العدد الثابت ; $6$\n| المطلوب ; بالتعريف ; $PF_1+PF_2=2a$\nmain: [تعريف القطع الناقص] مجموع البعدين ثابت\n| $$PF_1+PF_2=2a\n>>> ell #1 :: نكتب التعريف ونربّع\np: **الحل:** $\\forall\\,P(x,y)$ تنتمي للقطع الناقص :\n$$\\sqrt{(x-2)^2+y^2}+\\sqrt{(x+2)^2+y^2}=6\n$$\\sqrt{(x-2)^2+y^2}=6-\\sqrt{(x+2)^2+y^2}\np: بتربيع الطرفين\n$$x^2-4x+4+y^2=36-12\\sqrt{(x+2)^2+y^2}+x^2+4x+4+y^2\n$$12\\sqrt{(x+2)^2+y^2}=36+8x\n>>> ell ! #2 :: نربّع مرة ثانية ونبسّط\np: بالقسمة على 4\n$$3\\sqrt{(x+2)^2+y^2}=9+2x\np: بتربيع الطرفين\n$$9\\left[x^2+4x+4+y^2\\right]=81+36x+4x^2\n$$9x^2+36x+36+9y^2=81+36x+4x^2\n$$5x^2+9y^2=45\n$$\\frac{x^2}{9}+\\frac{y^2}{5}=1\np: معادلة القطع الناقص\nxp: فحص بالجدول\n| $a=3$ ، $c=2$ ⇐ $b^2=9-4=5$ ✓\n--- @practice تدرّب: تمارين ص 78–79 (المركز في نقطة الأصل)\n>>> eorient .book\nk: تمارين · ص 78\nh2: دورك الآن\np: **1.** عين كل من البؤرتين والرأسين والقطبين والمركز ثم جد طول ومعادلة كل من المحورين والاختلاف المركزي للقطوع الناقصة المبينة معادلتها في كل مما يأتي : **a)** $x^2+2y^2=1$\nxp: قالب الحل\n| **نجعل الطرف الأيمن 1** ← **المقام الأكبر** $a^2$ يحدد المحور ← **$c^2=a^2-b^2$** ← **العناصر** ← **فحص:** $e<1$\nnote: الفقرات c – f معادلاتها مركزها ليس في نقطة الأصل، فتأتي في درس [2−5] .\nself:\nsol: **الحل:**\n| let> المعادلة ; القياسية ; $\\dfrac{x^2}{1}+\\dfrac{y^2}{\\frac12}=1$\n| main> [القطع الناقص] $a^2=1\\ ,\\ b^2=\\tfrac12$\n| $$c=\\sqrt{1-\\tfrac12}=\\frac{1}{\\sqrt2}\n| البؤرتان $\\left(\\pm\\dfrac{1}{\\sqrt2},0\\right)$\n| الرأسان $(\\pm1,0)$\n| القطبان $\\left(0,\\pm\\dfrac{1}{\\sqrt2}\\right)$ ، والمركز $(0,0)$\n| المحور الكبير $y=0$ وطوله $2$\n| المحور الصغير $x=0$ وطوله $\\sqrt2$\n| $e=\\dfrac{1}{\\sqrt2}$\n>>> eorient .book\np: **b)** $9x^2+13y^2=117$\nself:\nhint: اقسم على 117 .\nsol: **الحل:**\n| let> المعادلة ; القياسية ; $\\dfrac{x^2}{13}+\\dfrac{y^2}{9}=1$\n| main> [القطع الناقص] $a^2=13\\ ,\\ b^2=9$\n| $$c=\\sqrt{13-9}=2\n| البؤرتان $(\\pm2,0)$\n| الرأسان $(\\pm\\sqrt{13},0)$\n| القطبان $(0,\\pm3)$ ، والمركز $(0,0)$\n| المحور الكبير $y=0$ وطوله $2\\sqrt{13}$\n| المحور الصغير $x=0$ وطوله $6$\n| $e=\\dfrac{2}{\\sqrt{13}}$\n>>> eorient .book\np: **2.** جد المعادلة القياسية للقطع الناقص الذي مركزه في نقطة الاصل في كل مما يأتي ثم ارسمه : **أ.** البؤرتان هما النقطتان $(0,5)$ و $(0,-5)$ وطول محوره الكبير يساوي (12) وحدة .\nself:\nsol: **الحل:**\n| let> $c$ ; نصف البعد البؤري ; $5$\n| let> $a$ ; نصف المحور الكبير ; $6$\n| main> [القطع الناقص] البؤرتان على محور الصادات\n| $$b^2=a^2-c^2=36-25=11\n| $\\dfrac{x^2}{11}+\\dfrac{y^2}{36}=1$\n>>> eorient .book\np: **ب.** البؤرتان هما $(\\pm2,0)$ ويتقاطع مع محور السينات عند $x=\\pm4$ .\nself:\nsol: **الحل:**\n| let> $c$ ; نصف البعد البؤري ; $2$\n| let> $a$ ; نصف المحور الكبير ; $4$\n| main> [القطع الناقص] البؤرتان على محور السينات\n| $$b^2=16-4=12\n| $\\dfrac{x^2}{16}+\\dfrac{y^2}{12}=1$\n>>> eorient .book\np: **ج.** احدى بؤرتيه تبعد عن نهايتي محوره الكبير بالعددين $1 , 5$ وحدة على الترتيب .\nself:\nhint: $a-c=1$ و $a+c=5$ .\nsol: **الحل:**\n| let> $a-c$ ; البعد الأصغر ; $1$\n| let> $a+c$ ; البعد الأكبر ; $5$\n| main> [القطع الناقص] العلاقة بين $a , b , c$\n| $$a=3\\ ,\\ c=2\\Rightarrow b^2=9-4=5\n| إذا كانت البؤرتان على محور السينات: $\\dfrac{x^2}{9}+\\dfrac{y^2}{5}=1$\n| » أو على محور الصادات: $\\dfrac{x^2}{5}+\\dfrac{y^2}{9}=1$\n>>> eorient .book\np: **د.** الاختلاف المركزي $=\\dfrac12$ وطول محوره الصغير (12) وحدة طولية .\nself:\nhint: $c=\\tfrac a2$ و $b=6$ .\nsol: **الحل:**\n| let> $e$ ; الاختلاف المركزي ; $\\dfrac12$\n| let> $b$ ; نصف المحور الصغير ; $6$\n| main> [القطع الناقص] $c=\\tfrac a2$\n| $$a^2-\\frac{a^2}{4}=36\\Rightarrow a^2=48\n| إذا كانت البؤرتان على محور السينات: $\\dfrac{x^2}{48}+\\dfrac{y^2}{36}=1$\n| » أو على محور الصادات: $\\dfrac{x^2}{36}+\\dfrac{y^2}{48}=1$\n>>> eorient .book\np: **هـ.** المسافة بين بؤرتيه تساوي (8) وحدات ، ونصف محوره الصغير يساوي (3) وحدة .\nself:\nsol: **الحل:**\n| let> $c$ ; نصف البعد البؤري ; $4$\n| let> $b$ ; نصف المحور الصغير ; $3$\n| main> [القطع الناقص] العلاقة بين $a , b , c$\n| $$a^2=b^2+c^2=9+16=25\n| إذا كانت البؤرتان على محور السينات: $\\dfrac{x^2}{25}+\\dfrac{y^2}{9}=1$\n| » أو على محور الصادات: $\\dfrac{x^2}{9}+\\dfrac{y^2}{25}=1$\n>>> ell .book\np: **3.** باستخدام التعريف جد معادلة القطع الناقص اذا علم : **أ.** بؤرتاه النقطتان $(0,\\pm2)$ وراساه النقطتان $(0,\\pm3)$ ومركزه نقطة الاصل .\nself:\nhint: كما في المثال 17 : $PF_1+PF_2=2a=6$ .\nsol: **الحل:**\n| let> $c$ ; نصف البعد البؤري ; $2$\n| let> $a$ ; نصف المحور الكبير ; $3$\n| main> [تعريف القطع الناقص] مجموع البعدين ثابت\n| $$\\sqrt{x^2+(y-2)^2}+\\sqrt{x^2+(y+2)^2}=6\n| بالتربيع مرتين كما في المثال 17 :\n| $9x^2+5y^2=45\\Rightarrow\\dfrac{x^2}{5}+\\dfrac{y^2}{9}=1$\n>>> ell .book\np: **ب.** المسافة بين البؤرتين (6) وحدة والعدد الثابت (10) والبؤرتان تقعان على محور السينات ومركزه نقطة الاصل .\nself:\nsol: **الحل:**\n| let> $c$ ; نصف البعد البؤري ; $3$\n| let> $a$ ; نصف المحور الكبير ; $5$\n| main> [تعريف القطع الناقص] مجموع البعدين ثابت\n| $$\\sqrt{(x-3)^2+y^2}+\\sqrt{(x+3)^2+y^2}=10\n| بالتربيع مرتين: $16x^2+25y^2=400\\Rightarrow\\dfrac{x^2}{25}+\\dfrac{y^2}{16}=1$\n>>> eorient .book\np: **4.** جد معادلة القطع الناقص الذي مركزه نقطة الاصل واحدى بؤرتيه هي بؤرة القطع المكافئ الذي معادلته $y^2+8x=0$ علماً بان القطع الناقص يمر بالنقطة $(2\\sqrt3\\ ,\\ \\sqrt3)$ .\nself:\nhint: بؤرة المكافئ $(-2,0)$ ⇐ $c=2$ و $b^2=a^2-4$ ، ثم عوّض النقطة.\nsol: **الحل:**\n| let> $c$ ; من بؤرة المكافئ ; $2$\n| main> [القطع الناقص] $b^2=a^2-4$\n| $$\\frac{12}{a^2}+\\frac{3}{a^2-4}=1\n| $a^4-19a^2+48=0\\Rightarrow(a^2-16)(a^2-3)=0$\n| $a^2=3$ يهمل لأن $a>c$ ⇐ $a^2=16\\ ,\\ b^2=12$\n| $\\dfrac{x^2}{16}+\\dfrac{y^2}{12}=1$\n>>> eorient .book\nk: ص 79\np: **5.** جد معادلة القطع الناقص الذي مركزه نقطة الاصل وبؤرتاه على محور السينات ويمر بالنقطتين $(3,4)\\ ,\\ (6,2)$ .\nself:\nhint: عوّض النقطتين فتحصل على معادلتين في $\\tfrac{1}{a^2}$ و $\\tfrac{1}{b^2}$ .\nsol: **الحل:**\n| let> النقطتان ; على القطع ; $(3,4)\\ ,\\ (6,2)$\n| main> [نعوّض النقطتين] $u=\\tfrac{1}{a^2}\\ ,\\ v=\\tfrac{1}{b^2}$\n| $$9u+16v=1\\ ,\\quad36u+4v=1\n| $u=\\dfrac{1}{45}\\ ,\\ v=\\dfrac{1}{20}$\n| $\\dfrac{x^2}{45}+\\dfrac{y^2}{20}=1$\n>>> eorient .book\np: **6.** جد معادلة القطع الناقص الذي مركزه نقطة الاصل وبؤرتاه نقطتا تقاطع المنحني $x^2+y^2-3x=16$ مع محور الصادات ويمس دليل القطع المكافئ $y^2=12x$ .\nself:\nhint: على محور الصادات $x=0$ ⇐ $y=\\pm4$ . ودليل المكافئ $x=-3$ .\nsol: **الحل:**\n| let> البؤرتان ; $x=0$ ; $(0,\\pm4)\\Rightarrow c=4$\n| let> المماس ; دليل المكافئ ; $x=-3\\Rightarrow b=3$\n| main> [القطع الناقص] البؤرتان على محور الصادات\n| $$a^2=b^2+c^2=9+16=25\n| $\\dfrac{x^2}{9}+\\dfrac{y^2}{25}=1$\n>>> eorient .book\np: **7.** جد معادلة القطع الناقص الذي بؤرتاه تنتميان الى محور السينات ومركزه في نقطة الاصل وطول محوره الكبير ضعف طول محوره الصغير ويقطع القطع المكافئ $y^2+8x=0$ عند النقطة التي احداثيها السيني يساوي $(-2)$ .\nself:\nhint: النقطة $(-2,\\pm4)$ ، و $a=2b$ .\nsol: **الحل:**\n| let> النقطة ; على المكافئ ; $(-2,4)$\n| main> [القطع الناقص] $a=2b$\n| $$\\frac{4}{4b^2}+\\frac{16}{b^2}=1\\Rightarrow b^2=17\n| $a^2=4b^2=68$\n| $\\dfrac{x^2}{68}+\\dfrac{y^2}{17}=1$\n>>> eorient .book\np: **8.** قطع ناقص معادلته $hx^2+ky^2=36$ ومركزه نقطة الاصل ومجموع مربعي طولي محوريه يساوي (60) ، واحدى بؤرتيه هي بؤرة القطع المكافئ الذي معادلته $y^2=4\\sqrt3\\,x$ ما قيمة كل من $h,k\\in R$ ؟\nprac: 4 , 6 ; h ، k\nhint: $(2a)^2+(2b)^2=60\\Rightarrow a^2+b^2=15$ ، و $c=\\sqrt3$ .\nsol: **الحل:**\n| let> $a^2+b^2$ ; ربع المجموع ; $15$\n| let> $c^2$ ; من بؤرة المكافئ ; $3$\n| main> [القطع الناقص] $a^2-b^2=c^2$\n| $$a^2=9\\ ,\\quad b^2=6\n| $\\dfrac{x^2}{9}+\\dfrac{y^2}{6}=1$ ، وبالضرب في 36 : $4x^2+6y^2=36$\n| $h=4\\ ,\\ k=6$\n>>> eorient .book\np: **9.** جد معادلة القطع الناقص الذي مركزه نقطة الاصل واحدى بؤرتيه هي بؤرة القطع المكافئ $x^2=24y$ ومجموع طولي محوريه (36) وحدة .\nself:\nhint: $c=6$ على محور الصادات، و $a+b=18$ .\nsol: **الحل:**\n| let> $c$ ; من بؤرة المكافئ ; $6$\n| let> $a+b$ ; نصف المجموع ; $18$\n| main> [القطع الناقص] $a^2-b^2=c^2$\n| $$(a-b)(a+b)=36\\Rightarrow a-b=2\n| $a=10\\ ,\\ b=8$\n| $\\dfrac{x^2}{64}+\\dfrac{y^2}{100}=1$\n>>> ell .book\np: **10.** جد معادلة القطع الناقص الذي بؤرتيه $F_1(4,0)\\ ,\\ F_2(-4,0)$ والنقطة $Q$ تنتمي للقطع الناقص بحيث ان محيط المثلث $QF_1F_2$ يساوي (24) وحدة .\nself:\nhint: محيط المثلث $=QF_1+QF_2+F_1F_2=2a+2c$ .\nsol: **الحل:**\n| let> المحيط ; $2a+2c$ ; $24$\n| main> [تعريف القطع الناقص] $QF_1+QF_2=2a$\n| $$2a+8=24\\Rightarrow a=8\n| $b^2=64-16=48$\n| $\\dfrac{x^2}{64}+\\dfrac{y^2}{48}=1$\n--- @check تحقّق\n>>> eorient .enr\nk: تقويم قصير · ليس من الكتاب\np: في القطع $\\dfrac{x^2}{9}+\\dfrac{y^2}{25}=1$ ، أين تقع البؤرتان؟\nask: اختر:\no: $(\\pm4,0)$\no*: $(0,\\pm4)$\no: $(0,\\pm3)$\nwhy: المقام الأكبر $25$ تحت $y^2$ ⇐ المحور الكبير على محور الصادات، و $c=\\sqrt{25-9}=4$ .\n>>> eorient .enr\np: أي قيمة لا يمكن أن تكون اختلافاً مركزياً لقطع ناقص؟\nask: اختر:\no: $0.2$\no: $0.9$\no*: $1.5$\nwhy: $e=\\tfrac ca$ و $c<a$ ، فالاختلاف المركزي للناقص أقل من 1 دائماً.\n>>> eorient .summary\nh2: الخلاصة\n- $PF_1+PF_2=2a$ ، و $c^2=a^2-b^2$ ، و $a>b$ ، $a>c$ .\n- المقام الأكبر $a^2$ يحدد محور البؤرتين: $\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1$ أو $\\dfrac{x^2}{b^2}+\\dfrac{y^2}{a^2}=1$ .\n- $e=\\tfrac ca<1$ ، $A=ab\\pi$ ، $P=2\\pi\\sqrt{\\tfrac{a^2+b^2}{2}}$ .\n\n=== etrans | 2−5 | انسحاب المحاور للقطع الناقص | 75–78 | المركز (h , k) : (x − h)²/a² + (y − k)²/b² = 1 أو (x − h)²/b² + (y − k)²/a² = 1 ، والعناصر كلها تنسحب مع المركز.\n--- @discover اكتشف: القطع نفسه حول مركز جديد\n>>> etrans .act\nk: [2−5] · انسحاب المحاور للقطع الناقص\nh1: المركز ينتقل إلى (h , k)\nlead: عندما ينتقل المركز من $(0,0)$ إلى $\\cf{(h , k)}$ تبقى $a , b , c$ كما هي، وتنسحب البؤرتان والرأسان والقطبان معه.\np: **حرّك الانسحاب** أو **اسحب المركز** إلى أي موضع لترى كل حالات h و k ، والمعادلة تتغير معه. هذا قطع المثال 18 ، ومركزه $(2,1)$ .\n>>>\nask: القطع $\\dfrac{x^2}{16}+\\dfrac{y^2}{9}=1$ انسحب فصار مركزه $(1,-2)$ . ما معادلته؟\no: $\\dfrac{(x+1)^2}{16}+\\dfrac{(y-2)^2}{9}=1$\no*: $\\dfrac{(x-1)^2}{16}+\\dfrac{(y+2)^2}{9}=1$\no: $\\dfrac{(x-1)^2}{9}+\\dfrac{(y+2)^2}{16}=1$\nwhy: نستبدل $x$ بـ $x-h=x-1$ و $y$ بـ $y-k=y+2$ ، والمقامات لا تتغير.\n--- @understand افهم: المعادلتان بعد الانسحاب\n>>> etrans .book\nk: [2−5] · ص 75\np: تبينا ان مركز القطع الناقص بانه نقطة تقاطع محوري تناظره ، فاذا كان المركز عند النقطة $c(h,k)$ والمحوران يوازيان المحورين الاحداثيين فاننا نحصل على معادلة القطع الناقص في الاحداثيات الجديدة كما يأتي :\nh2: [2−5−1] المعادلة القياسية للقطع الناقص الذي محوره الاكبر يوازي المحور السيني ومركزه النقطة (h , k)\np: عند انسحاب مركز القطع الناقص الذي مركزه نقطة الاصل $(0,0)$ على محور السينات بمقدار $h$ من الوحدات وبمقدار $k$ من الوحدات على محور الصادات ، تصبح المعادلة القياسية للقطع الناقص بالصورة الاتية :\nlaw:\n| $$\\frac{(x-h)^2}{a^2}+\\frac{(y-k)^2}{b^2}=1\np: لاحظ من الشكل (2−19) ان المحور الكبير يوازي محور السينات وطوله $(2a)$ ومعادلته $y=k$ والمحور الصغير يوازي محور الصادات وطوله $(2b)$ ومعادلته $x=h$ أما البؤرتان بعد الانسحاب فتصبحان $\\overline{F_1}(c+h,k)\\ ,\\ \\overline{F_2}(-c+h,k)$ والرأسان للقطع الناقص هما $\\overline{V_1}(a+h,k)\\ ,\\ \\overline{V_2}(-a+h,k)$\n>>> etrans .book\nk: ص 76\nh2: [2−5−2] المعادلة القياسية للقطع الناقص الذي محوره الاكبر يوازي محور الصادات ومركزه النقطة (h , k)\np: بنفس الاسلوب السابق لمعادلة القطع الناقص الذي محوره الاكبر يوازي محور السينات ومركزه النقطة $(h,k)$ يمكن التعرف على المعادلة القياسية للقطع الناقص الذي محوره الاكبر يوازي محور الصادات ومركزه النقطة $(h,k)$ وهي : لاحظ الشكل (2−20)\nlaw:\n| $$\\frac{(x-h)^2}{b^2}+\\frac{(y-k)^2}{a^2}=1\n| حيث البؤرتان هما $\\overline{F_1}(h,c+k)\\ ,\\ \\overline{F_2}(h,-c+k)$\n| والرأسان $\\overline{V_1}(h,a+k)\\ ,\\ \\overline{V_2}(h,-a+k)$\np: والمحور الكبير يوازي محور الصادات وطوله $(2a)$ ومعادلته $x=h$ اما المحور الصغير فانه يوازي محور السينات وطوله $(2b)$ ومعادلته $y=k$ .\nnote: سنقتصر في البند [2−5] على إيجاد مركز القطع الناقص ، والبؤرتان والرأسان والقطبان ، وطول المحورين ومعادلة كل من المحورين فقط .\n--- @learn تعلّم الحل: المركز أولاً ثم نضيف إليه\n>>> etrans .book\nk: فكرة الحل في هذا الدرس\nh2: نحسب كأن المركز في الأصل ثم نزيح\nxp: فكرة الحل في هذا الدرس\n| **1) نكمل المربعين** إن لزم، ونجعل الطرف الأيمن $1$ .\n| **2) المركز** $(h,k)$ بإشارة معاكسة لما داخل القوسين.\n| **3) المقام الأكبر** $a^2$ يحدد اتجاه المحور الكبير، و $c^2=a^2-b^2$ .\n| **4) نضيف** $\\pm a$ و $\\pm c$ إلى إحداثي المركز على اتجاه المحور الكبير، و $\\pm b$ على الاتجاه الآخر.\n| **فحص:** المركز منتصف البؤرتين ومنتصف الرأسين.\n>>> etrans .book\nk: مثال 18 · ص 77\nh2: المحور الكبير يوازي محور الصادات\np: جد البؤرتين والرأسين والقطبين وطول ومعادلة كل من المحورين للقطع الناقص ثم جد قيمة $e$ .\n$$\\frac{(x-2)^2}{9}+\\frac{(y-1)^2}{25}=1\nlet: المعطيات\n| المعادلة ; المعطاة ; $\\dfrac{(x-2)^2}{9}+\\dfrac{(y-1)^2}{25}=1$\n| المقام الأكبر ; تحت $(y-k)^2$ ; المحور الكبير يوازي محور الصادات\n| المطلوب ; العناصر والاختلاف المركزي ; $e$\nmain: [المعادلة القياسية] المحور الكبير يوازي محور الصادات\n| $$\\frac{(x-h)^2}{b^2}+\\frac{(y-k)^2}{a^2}=1\n>>> etrans #1 :: المركز والمحوران\np: **الحل:** بالمقارنة مع المعادلة القياسية للقطع الناقص .\n$$\\Rightarrow(h,k)=(2,1)\n$$\\Rightarrow a^2=25\\Rightarrow a=5\\Rightarrow2a=10\np: طول المحور الكبير ، وحدة\n$$b^2=9\\Rightarrow b=3\\Rightarrow2b=6\np: طول المحور الصغير ، وحدة\n$$c=\\sqrt{a^2-b^2}\\Rightarrow c=\\sqrt{25-9}=\\sqrt{16}=4\n>>> etrans #2 :: البؤرتان والرأسان والقطبان\np: البؤرتان\n$$\\overline{F_1}(h,c+k)\\ ,\\ \\overline{F_2}(h,-c+k)\n$$\\overline{F_1}(2,5)\\ ,\\ \\overline{F_2}(2,-3)\np: الرأسان\n$$\\overline{V_1}(h,a+k)\\ ,\\ \\overline{V_2}(h,-a+k)\n$$\\overline{V_1}(2,6)\\ ,\\ \\overline{V_2}(2,-4)\np: القطبان\n$$(-b+h,k)\\ ,\\ (b+h,k)\n$$(-1,1)\\ ,\\ (5,1)\n>>> etrans ! #3 :: المحوران و e\np: معادلة المحور الكبير\n$$\\therefore\\ x=2\np: معادلة المحور الصغير\n$$y=1\n$$e=\\frac ca=\\frac45<1\np: (الاختلاف المركزي)\nxp: فحص\n| المركز $(2,1)$ منتصف البؤرتين: $\\tfrac{5+(-3)}{2}=1$ ✓ ، ومنتصف الرأسين: $\\tfrac{6+(-4)}{2}=1$ ✓\n--- @practice تدرّب: تمارين ص 78 (مركز ليس في نقطة الأصل)\n>>> etrans .book\nk: تمارين · 1 · ص 78\nh2: دورك الآن\np: **1.** عين كل من البؤرتين والرأسين والقطبين والمركز ثم جد طول ومعادلة كل من المحورين والاختلاف المركزي للقطوع الناقصة المبينة معادلتها في كل مما يأتي : **c)** $\\dfrac{(x-4)^2}{81}+\\dfrac{(y+1)^2}{25}=1$\nxp: قالب الحل\n| **المركز** $(h,k)$ ← **المقام الأكبر** $a^2$ واتجاهه ← **$c$** ← **نضيف** $\\pm a$ و $\\pm c$ و $\\pm b$ إلى المركز ← **فحص:** المركز منتصف البؤرتين\nself:\nsol: **الحل:**\n| let> المركز ; $(h,k)$ ; $(4,-1)$\n| let> $a$ ; المحور الكبير يوازي محور السينات ; $9$\n| let> $b$ ; نصف المحور الصغير ; $5$\n| main> [المعادلة القياسية] $c^2=a^2-b^2$\n| $$c=\\sqrt{81-25}=2\\sqrt{14}\n| البؤرتان $(4\\pm2\\sqrt{14}\\ ,\\ -1)$\n| الرأسان $(13,-1)\\ ,\\ (-5,-1)$\n| القطبان $(4,4)\\ ,\\ (4,-6)$\n| المحور الكبير $y=-1$ وطوله $18$\n| المحور الصغير $x=4$ وطوله $10$\n| $e=\\dfrac{2\\sqrt{14}}{9}$\n>>> etrans .book\np: **d)** $\\dfrac{(x+3)^2}{9}+\\dfrac{(y+2)^2}{25}=1$\nself:\nsol: **الحل:**\n| let> المركز ; $(h,k)$ ; $(-3,-2)$\n| let> $a$ ; المحور الكبير يوازي محور الصادات ; $5$\n| let> $b$ ; نصف المحور الصغير ; $3$\n| main> [المعادلة القياسية] $c^2=a^2-b^2$\n| $$c=\\sqrt{25-9}=4\n| البؤرتان $(-3,2)\\ ,\\ (-3,-6)$\n| الرأسان $(-3,3)\\ ,\\ (-3,-7)$\n| القطبان $(0,-2)\\ ,\\ (-6,-2)$\n| المحور الكبير $x=-3$ وطوله $10$\n| المحور الصغير $y=-2$ وطوله $6$\n| $e=\\dfrac45$\n>>> etrans .book\np: **e)** $9x^2+16y^2-72x-96y+144=0$\nself:\nhint: $9(x^2-8x+16)+16(y^2-6y+9)=-144+144+144$\nsol: **الحل:**\n| let> المعادلة ; بعد إكمال المربعين ; $\\dfrac{(x-4)^2}{16}+\\dfrac{(y-3)^2}{9}=1$\n| main> [المعادلة القياسية] المحور الكبير يوازي محور السينات\n| $$c=\\sqrt{16-9}=\\sqrt7\n| المركز $(4,3)$\n| البؤرتان $(4\\pm\\sqrt7\\ ,\\ 3)$\n| الرأسان $(8,3)\\ ,\\ (0,3)$\n| القطبان $(4,6)\\ ,\\ (4,0)$\n| المحور الكبير $y=3$ وطوله $8$\n| المحور الصغير $x=4$ وطوله $6$\n| $e=\\dfrac{\\sqrt7}{4}$\n>>> etrans .book\np: **f)** $x^2+25y^2+4x-150y+204=0$\nself:\nhint: $(x^2+4x+4)+25(y^2-6y+9)=-204+4+225$\nsol: **الحل:**\n| let> المعادلة ; بعد إكمال المربعين ; $\\dfrac{(x+2)^2}{25}+\\dfrac{(y-3)^2}{1}=1$\n| main> [المعادلة القياسية] المحور الكبير يوازي محور السينات\n| $$c=\\sqrt{25-1}=2\\sqrt6\n| المركز $(-2,3)$\n| البؤرتان $(-2\\pm2\\sqrt6\\ ,\\ 3)$\n| الرأسان $(3,3)\\ ,\\ (-7,3)$\n| القطبان $(-2,4)\\ ,\\ (-2,2)$\n| المحور الكبير $y=3$ وطوله $10$\n| المحور الصغير $x=-2$ وطوله $2$\n| $e=\\dfrac{2\\sqrt6}{5}$\n--- @check تحقّق\n>>> etrans .enr\nk: تقويم قصير · ليس من الكتاب\np: ما مركز القطع $\\dfrac{(x+5)^2}{4}+\\dfrac{(y-1)^2}{9}=1$ ؟\nask: اختر:\no: $(5,-1)$\no*: $(-5,1)$\no: $(1,-5)$\nwhy: $x-h=x+5\\Rightarrow h=-5$ و $y-k=y-1\\Rightarrow k=1$ .\n>>> etrans .enr\np: في القطع نفسه، المحور الكبير يوازي:\nask: اختر:\no: محور السينات\no*: محور الصادات\no: لا يوازي أياً منهما\nwhy: المقام الأكبر $9$ تحت $(y-k)^2$ ، فالمحور الكبير عمودي ومعادلته $x=-5$ .\n>>> etrans .summary\nh2: الخلاصة\n- المركز $(h,k)$ : $\\dfrac{(x-h)^2}{a^2}+\\dfrac{(y-k)^2}{b^2}=1$ (المحور الكبير أفقي) أو $\\dfrac{(x-h)^2}{b^2}+\\dfrac{(y-k)^2}{a^2}=1$ (عمودي).\n- نحسب $a , b , c$ كالعادة ثم نضيفها إلى إحداثي المركز.\n- المحور الكبير $y=k$ أو $x=h$ ، والصغير عمودي عليه من المركز.\n\n=== hyperb | 2−6 | القطع الزائد | 80–89 | المركز في نقطة الأصل: x²/a² − y²/b² = 1 أو y²/a² − x²/b² = 1 ، مع c² = a² + b² ، والاختلاف المركزي e = c/a > 1 ، والرسم بالمستطيل والمستقيمين المحاذيين.\n--- @discover اكتشف: فرق بعدين ثابت\n>>> hyp .act\nk: [2−6] · القطع الزائد · Hyperbola\nh1: الفرق ثابت هذه المرة\nlead: في الناقص كان **مجموع** البعدين عن البؤرتين ثابتاً. في الزائد **القيمة المطلقة للفرق** بينهما ثابتة وتساوي $\\cf{2a}$ .\np: **حرّك P** على الفرعين: الطولان يكبران معاً، وفرقهما يبقى $16$ .\n>>>\nask: نقطة على قطع زائد فيه $2a=16$ ، بعدها عن إحدى البؤرتين $20$ . ما بعدها عن الأخرى؟\no: $36$ فقط\no: $4$ فقط\no*: $4$ أو $36$\nwhy: $|PF_1-PF_2|=16$ ⇐ البعد الآخر $20-16=4$ أو $20+16=36$ (حسب الفرع).\n--- @understand افهم: التعريف والمعادلتان والرسم\n>>> hyp .book\nk: [2−6] · ص 80\nlaw: تعريف [2−6−1]\n| القطع الزائد هو مجموعة النقط في المستوي التي تكون القيمة المطلقة لفرق بعدي اي منها عن نقطتين ثابتتين (البؤرتان) يساوي عدداً ثابتاً .\np: كما في الشكل (2−22) البؤرتان هما $F_1(c,0)\\ ,\\ F_2(-c,0)$ الرأسان هما $V_1(a,0)\\ ,\\ V_2(-a,0)$ والنقطة $P(x,y)$ نقطة من نقاط منحني القطع الزائد ومن التعريف [2−6]\n$$|PF_1-PF_2|=2a\np: حيث $2a$ عدداً ثابتاً يمثل طول المحور الحقيقي للقطع الزائد الذي تقع عليه البؤرتين والرأسين وكل من $PF_1 , PF_2$ يسميان طولي نصفي القطريين البؤريين المرسومين من نقطة $(P)$ والمسافة $F_1F_2$ هي البعد بين البؤرتين وتساوي $2c$ وطول المحور المرافق او التخيلي هو $(2b)$ (وهو المحور العمودي على المحور الحقيقي والمار بمركز القطع) .\n>>> hyp .book\nk: [2−6−2] · ص 81\nh2: معادلة القطع الزائد الذي بؤرتاه على محور السينات ومركزه نقطة الاصل\np: من الشكل (2−22) وتبعاً لتعريف القطع الزائد :\n$$|PF_1-PF_2|=2a\\Rightarrow PF_1-PF_2=\\pm2a\n$$\\Rightarrow\\sqrt{(x-c)^2+y^2}-\\sqrt{(x+c)^2+y^2}=\\pm2a\n$$\\Rightarrow\\sqrt{(x-c)^2+y^2}=\\pm2a+\\sqrt{(x+c)^2+y^2}\np: وبتربيع الطرفين والتبسيط كما مر في معادلة القطع الناقص الذي مركزه نقطة الاصل والبؤرتان على محور السينات نحصل على المعادلة :\n$$\\frac{x^2}{a^2}+\\frac{y^2}{a^2-c^2}=1\np: من الشكل (2−22) فان : $c>0\\ ,\\ a>0\\ ,\\ c>a$ ⇐ $c^2-a^2>0$ ، وبفرض ان $b^2=c^2-a^2$\nlaw: وبتعويض عن $a^2-c^2=-b^2$ في المعادلة القياسية السابقة نحصل على :\n| $$\\frac{x^2}{a^2}-\\frac{y^2}{b^2}=1\n>>> horient .book\nk: [2−6−3] · ص 82\nh2: معادلة القطع الزائد الذي بؤرتاه على محور الصادات ومركزه نقطة الاصل\np: اذا كانت البؤرتان على محور الصادات ومحور السينات هو العمود على $F_1F_2$ من نقطة الاصل كما في الشكل (2−23) وبنفس الطريقة السابقة نجد المعادلة القياسية للقطع الزائد . وهي :\nlaw:\n| $$\\frac{y^2}{a^2}-\\frac{x^2}{b^2}=1\nnote: **ملاحظة:** الاختلاف المركزي $e$ للقطع الزائد يكون أكبر من واحد أي $e=\\dfrac ca>1$\n>>> horient .book\nk: [2−6−4] · Graph The Hyperbola · ص 82–83\nh2: طريقة رسم القطع الزائد\np: لتكن $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1$ معادلة قطع زائد بؤرتاه تنتميان لمحور السينات ولرسم هذا القطع :\nlaw: خطوات الرسم\n| **1.** نعين النقطتين $(a,0)\\ ,\\ (-a,0)$ .\n| **2.** نعين النقطتين $(0,b)\\ ,\\ (0,-b)$ .\n| **3.** نكون مستطيلاً من هذه النقط أضلاعه تـوازي المحورين كما في الشكل (2−24) .\n| **4.** نرسم قطري المستطيل كما في الشكل (2−24) فهما يمثلان المستقيمين المحاذيين لمنحني القطع الزائد .\n| **5.** نعين البؤرتين $F_1(c,0)\\ ,\\ F_2(-c,0)$ ثم نرسم ذراعي القطع الزائد كما في الشكل (2−25) .\n--- @learn تعلّم الحل: الحد الموجب يحدد المحور\n>>> horient .book\nk: فكرة الحل في هذا الدرس\nh2: ثلاث فروق عن الناقص\nxp: فكرة الحل في هذا الدرس\n| **1) المحور الحقيقي** تحت الحد **الموجب** (لا المقام الأكبر): $x^2$ موجب ⇐ البؤرتان على محور السينات.\n| **2) $a^2$** هو مقام الحد الموجب، وقد يكون أصغر من $b^2$ .\n| **3) $c^2=a^2+b^2$** (جمع لا طرح)، فـ $c>a$ و $e=\\tfrac ca>1$ .\n| **فحص:** $c$ أكبر من $a$ ومن $b$ دائماً.\n>>> horient .book\nk: مثال 19 · ص 84\nh2: العناصر والرسم\np: عين البؤرتين والرأسين وطول كل من المحورين الحقيقي والمرافق للقطع الزائد ثم أرسمه .\n$$\\frac{x^2}{64}-\\frac{y^2}{36}=1\nlet: المعطيات\n| المعادلة ; المعطاة ; $\\dfrac{x^2}{64}-\\dfrac{y^2}{36}=1$\n| الحد الموجب ; $x^2$ ; البؤرتان على محور السينات\n| المطلوب ; العناصر ; ثم الرسم\nmain: [القطع الزائد] جمع لا طرح\n| $$c^2=a^2+b^2\n>>> hyp #1 :: المحوران\np: **الحل:** بالمقارنة مع المعادلة القياسية $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1$\n$$\\Rightarrow a^2=64\\Rightarrow a=8\\Rightarrow2a=16\np: طول المحور الحقيقي ، وحدة\n$$\\Rightarrow b^2=36\\Rightarrow b=6\\Rightarrow2b=12\np: طول المحور المرافق ، وحدة\n>>> hyp ! #2 :: c والبؤرتان والرأسان\n$$c^2=a^2+b^2\\Rightarrow c^2=64+36\n$$\\Rightarrow c^2=100\\Rightarrow c=10\np: رأسا القطع الزائد هما $V_1(8,0)\\ ,\\ V_2(-8,0)$\np: والبؤرتان هما $F_1(10,0)\\ ,\\ F_2(-10,0)$ . الشكل (2−26)\nxp: فحص\n| $c=10>a=8$ ✓\n| $e=\\tfrac{10}{8}=1.25>1$ ✓\n>>> horient .book\nk: مثال 20 · ص 84\nh2: من المحور والاختلاف المركزي\np: جد معادلة القطع الزائد الذي مركزه نقطة الاصل وطول محوره الحقيقي $6$ وحدات والاختلاف المركزي يساوي (2) والبؤرتان على محور السينات .\nerr: في الكتاب «وطول محوره الحقيقي − 6 وحدات» والشرطة زائدة، والمقصود $2a=6$ .\nlet: المعطيات\n| $2a$ ; المحور الحقيقي ; $6$\n| $e$ ; الاختلاف المركزي ; $2$\n| المطلوب ; المعادلة ; $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1$\nmain: [القطع الزائد] $e=\\tfrac ca$\n| $$c^2=a^2+b^2\n>>> horient #1 :: a و c\n$$2a=6\\Rightarrow a=3\\Rightarrow a^2=9\n$$\\therefore\\ e=\\frac ca\\Rightarrow2=\\frac c3\\Rightarrow c=6\n>>> horient ! #2 :: b² والمعادلة\n$$\\therefore\\ c^2=a^2+b^2\\Rightarrow36=9+b^2\n$$\\Rightarrow b^2=36-9\\Rightarrow b^2=27\n$$\\therefore\\ \\frac{x^2}{9}-\\frac{y^2}{27}=1\np: معادلة القطع الزائد القياسية\nxp: فحص\n| $c^2=9+27=36\\Rightarrow c=6$ ✓\n| $e=\\tfrac63=2$ ✓\n>>> horient .book\nk: مثال 21 · ص 85\nh2: القطع الزائد القائم\np: جد معادلة القطع الزائد الذي مركزه نقطة الاصل وطول محوره المرافق 4 وحدات وبؤرتاه هما النقطتان : $F_1(0,\\sqrt8)\\ ,\\ F_2(0,-\\sqrt8)$\nlet: المعطيات\n| $2b$ ; المحور المرافق ; $4$\n| البؤرتان ; على محور الصادات ; $(0,\\pm\\sqrt8)$\n| المطلوب ; المعادلة ; $\\dfrac{y^2}{a^2}-\\dfrac{x^2}{b^2}=1$\nmain: [القطع الزائد] البؤرتان على محور الصادات\n| $$c^2=a^2+b^2\n>>> horient #1 :: b و c\np: **الحل:** بما ان البؤرتين على محور الصادات فمعادلته القياسية $\\dfrac{y^2}{a^2}-\\dfrac{x^2}{b^2}=1$\n$$2b=4\\Rightarrow b=2\\Rightarrow b^2=4\n$$c=\\sqrt8\\Rightarrow c^2=8\n>>> horient ! #2 :: a² والمعادلة\n$$c^2=a^2+b^2\\qquad\\therefore\\ 8=a^2+4\n$$a^2=4\n$$\\frac{y^2}{4}-\\frac{x^2}{4}=1\np: في هذا المثال طول المحور الحقيقي مساوٍ الى طول المحور المرافق مثل هذا النوع من القطوع الزائدة يدعى بالقطع الزائد القائم او (المتساوي الاضلاع) لان النقاط الاربع تشكل رؤوس مربع وفيه يكون الاختلاف المركزي $(e)$ مقدار ثابت قيمته $(\\sqrt2)$ .\nxp: لماذا √2؟\n| $a=b$ ⇐ $c^2=2a^2$ ⇐ $c=\\sqrt2\\,a$ ⇐ $e=\\tfrac ca=\\sqrt2$ . هنا $\\tfrac{\\sqrt8}{2}=\\sqrt2$ ✓\n--- @practice تدرّب: تمارين ص 89 (المركز في نقطة الأصل)\n>>> horient .book\nk: تمارين · ص 89\nh2: دورك الآن\np: **1.** عين كل من البؤرتين والرأسين ثم جد طول كل من المحورين والاختلاف المركزي للقطوع الزائدة الاتية : **a)** $12x^2-4y^2=48$\nxp: قالب الحل\n| **نجعل الطرف الأيمن 1** ← **الحد الموجب** يحدد المحور و $a^2$ ← **$c^2=a^2+b^2$** ← **العناصر** ← **فحص:** $e>1$\nnote: الفقرتان c , d مركزهما ليس في نقطة الأصل، فتأتيان في درس [2−7] .\nself:\nhint: اقسم على 48 .\nsol: **الحل:**\n| let> المعادلة ; القياسية ; $\\dfrac{x^2}{4}-\\dfrac{y^2}{12}=1$\n| main> [القطع الزائد] $a^2=4\\ ,\\ b^2=12$\n| $$c=\\sqrt{4+12}=4\n| البؤرتان $(\\pm4,0)$\n| الرأسان $(\\pm2,0)$\n| المحور الحقيقي $4$\n| المحور المرافق $4\\sqrt3$\n| $e=\\dfrac42=2$\n>>> horient .book\np: **b)** $16x^2-9y^2=144$\nself:\nsol: **الحل:**\n| let> المعادلة ; القياسية ; $\\dfrac{x^2}{9}-\\dfrac{y^2}{16}=1$\n| main> [القطع الزائد] $a^2=9\\ ,\\ b^2=16$\n| $$c=\\sqrt{9+16}=5\n| البؤرتان $(\\pm5,0)$\n| الرأسان $(\\pm3,0)$\n| المحور الحقيقي $6$\n| المحور المرافق $8$\n| $e=\\dfrac53$\n>>> horient .book\np: **2.** اكتب معادلة القطع الزائد في الحالات الاتية ثم ارسم القطع : **أ.** البؤرتان هما النقطتان $(\\pm5,0)$ ويتقاطع مع محور السينات عند $x=\\pm3$ ومركزه نقطة الاصل .\nself:\nsol: **الحل:**\n| let> $c$ ; من البؤرتين ; $5$\n| let> $a$ ; من الرأسين ; $3$\n| main> [القطع الزائد] $b^2=c^2-a^2$\n| $$b^2=25-9=16\n| $\\dfrac{x^2}{9}-\\dfrac{y^2}{16}=1$\n>>> horient .book\np: **ب.** طول محوره الحقيقي (12) وحدة وطول محوره المرافق (10) وحدات وينطبق محوراه على المحورين الاحداثيين ومركزه نقطة الاصل .\nself:\nsol: **الحل:**\n| let> $a$ ; نصف المحور الحقيقي ; $6$\n| let> $b$ ; نصف المحور المرافق ; $5$\n| main> [القطع الزائد] المحور الحقيقي غير محدد\n| $$\\frac{x^2}{a^2}-\\frac{y^2}{b^2}=1\\quad\\text{or}\\quad\\frac{y^2}{a^2}-\\frac{x^2}{b^2}=1\n| $\\dfrac{x^2}{36}-\\dfrac{y^2}{25}=1$\n| » أو $\\dfrac{y^2}{36}-\\dfrac{x^2}{25}=1$\n>>> horient .book\np: **ج.** مركزه نقطة الاصل وبؤرتاه على محور الصادات وطول محوره المرافق $2\\sqrt2$ وحدة واختلافه المركزي يساوي $(3)$ .\nself:\nhint: $b=\\sqrt2$ و $c=3a$ .\nsol: **الحل:**\n| let> $b$ ; نصف المحور المرافق ; $\\sqrt2$\n| let> $e$ ; الاختلاف المركزي ; $3\\Rightarrow c=3a$\n| main> [القطع الزائد] $c^2=a^2+b^2$\n| $$9a^2=a^2+2\\Rightarrow a^2=\\frac14\n| $\\dfrac{y^2}{\\frac14}-\\dfrac{x^2}{2}=1$\n>>> hyp .book\np: **3.** جد باستخدام تعريف معادلة القطع الزائد الذي مركزه نقطة الاصل وبؤرتيه $(2\\sqrt2,0)\\ ,\\ (-2\\sqrt2,0)$ وينطبق محوراه على المحورين الاحداثيين والقيمة المطلقة للفرق بين بعدي اية نقطة عن بؤرتيه يساوي (4) وحدات .\nself:\nhint: $|PF_1-PF_2|=4$ ، ثم التربيع مرتين.\nsol: **الحل:**\n| let> $c$ ; من البؤرتين ; $2\\sqrt2$\n| let> $2a$ ; الفرق الثابت ; $4$\n| main> [تعريف القطع الزائد] الفرق المطلق ثابت\n| $$\\sqrt{(x-2\\sqrt2)^2+y^2}-\\sqrt{(x+2\\sqrt2)^2+y^2}=\\pm4\n| بالتربيع مرتين: $x^2-y^2=4$\n| $\\dfrac{x^2}{4}-\\dfrac{y^2}{4}=1$\n>>> horient .book\np: **4.** قطع زائد طول محوره الحقيقي (6) وحدات واحدى بؤرتيه هي بؤرة القطع المكافئ الذي رأسه نقطة الاصل ويمر بالنقطتين $(1,2\\sqrt5)\\ ,\\ (1,-2\\sqrt5)$ . جد معادلتي القطع المكافئ والقطع الزائد الذي مركزه نقطة الاصل .\nself:\nhint: النقطتان متناظرتان حول المحور السيني ⇐ $y^2=4px$ .\nsol: **الحل:**\n| let> المكافئ ; يمر بـ ; $(1,2\\sqrt5)$\n| main> [المكافئ ثم الزائد] $c=p$\n| $$20=4p(1)\\Rightarrow p=5\n| المكافئ: $y^2=20x$ ، وبؤرته $(5,0)$\n| الزائد: $a=3\\ ,\\ c=5\\Rightarrow b^2=16$\n| $\\dfrac{x^2}{9}-\\dfrac{y^2}{16}=1$\n>>> horient .book\np: **5.** قطع زائد مركزه نقطة الاصل ومعادلته $hx^2-ky^2=90$ وطول محوره الحقيقي $(6\\sqrt2)$ وحدة وبؤرتاه تنطبقان على بؤرتي القطع الناقص الذي معادلته $9x^2+16y^2=576$ جد قيمة كل من $h , k$ التي تنتمي الى مجموعة الاعداد الحقيقية .\nprac: 5 , 9 ; h ، k\nhint: الناقص: $\\dfrac{x^2}{64}+\\dfrac{y^2}{36}=1$ ⇐ $c^2=28$ .\nsol: **الحل:**\n| let> $a^2$ ; من $2a=6\\sqrt2$ ; $18$\n| let> $c^2$ ; من بؤرتي الناقص ; $64-36=28$\n| main> [القطع الزائد] $b^2=c^2-a^2$\n| $$b^2=28-18=10\n| $\\dfrac{x^2}{18}-\\dfrac{y^2}{10}=1$ ، وبالضرب في 90 : $5x^2-9y^2=90$\n| $h=5\\ ,\\ k=9$\n>>> horient .book\np: **6.** اكتب معادلة القطع الزائد الذي مركزه نقطة الاصل اذا علمت ان احد راسيه يبعد عن البؤرتين بالعددين $1 , 9$ وحدات على الترتيب وينطبق محوراه على المحورين الاحداثيين .\nself:\nhint: $c-a=1$ و $c+a=9$ .\nsol: **الحل:**\n| let> $c-a$ ; البعد الأصغر ; $1$\n| let> $c+a$ ; البعد الأكبر ; $9$\n| main> [القطع الزائد] $b^2=c^2-a^2$\n| $$c=5\\ ,\\ a=4\\Rightarrow b^2=9\n| $\\dfrac{x^2}{16}-\\dfrac{y^2}{9}=1$\n| » أو $\\dfrac{y^2}{16}-\\dfrac{x^2}{9}=1$\n>>> horient .book\np: **7.** جد معادلة القطع الناقص الذي بؤرتاه هما بؤرتا القطع الزائد الذي معادلته $x^2-3y^2=12$ والنسبة بين طولي محوريه $=\\dfrac53$ ومركزه نقطة الاصل .\nself:\nhint: الزائد: $\\dfrac{x^2}{12}-\\dfrac{y^2}{4}=1$ ⇐ $c^2=16$ .\nsol: **الحل:**\n| let> $c$ ; من بؤرتي الزائد ; $4$\n| let> $a : b$ ; النسبة ; $5t : 3t$\n| main> [القطع الناقص] $c^2=a^2-b^2$\n| $$25t^2-9t^2=16\\Rightarrow t=1\n| $a=5\\ ,\\ b=3$\n| $\\dfrac{x^2}{25}+\\dfrac{y^2}{9}=1$\n>>> hyp .book\np: **8.** النقطة $P(6,L)$ تنتمي الى القطع الزائد الذي مركزه نقطة الاصل ومعادلته $x^2-3y^2=12$ جد كلاً من : **أ.** قيمة $L$ **ب.** طول نصف القطر البؤري للقطع المرسوم في الجهة اليمنى من النقطة $P$ .\nself:\nhint: عوّض $x=6$ ، والبؤرة اليمنى $(4,0)$ .\nsol: **الحل:**\n| let> $P$ ; على القطع ; $(6,L)$\n| let> $F_1$ ; البؤرة اليمنى ; $(4,0)$\n| main> [نعوّض ثم قانون المسافة] $c^2=12+4$\n| $$36-3L^2=12\\Rightarrow L^2=8\\Rightarrow L=\\pm2\\sqrt2\n| $PF_1=\\sqrt{(6-4)^2+8}=\\sqrt{12}=2\\sqrt3$\n>>> horient .book\np: **9.** جد معادلة القطع الزائد الذي بؤرتاه هما بؤرتي القطع الناقص $\\dfrac{x^2}{9}+\\dfrac{y^2}{25}=1$ ويمس دليل القطع المكافئ $x^2+12y=0$ .\nself:\nhint: بؤرتا الناقص $(0,\\pm4)$ ، ودليل المكافئ $y=3$ : الزائد يمسه عند رأسه.\nsol: **الحل:**\n| let> $c$ ; من بؤرتي الناقص ; $4$\n| let> $a$ ; الرأس على الدليل $y=3$ ; $3$\n| main> [القطع الزائد] البؤرتان على محور الصادات\n| $$b^2=c^2-a^2=16-9=7\n| $\\dfrac{y^2}{9}-\\dfrac{x^2}{7}=1$\n--- @check تحقّق\n>>> horient .enr\nk: تقويم قصير · ليس من الكتاب\np: في القطع $\\dfrac{y^2}{9}-\\dfrac{x^2}{16}=1$ ، ما قيمة $c$ ؟\nask: اختر:\no: $\\sqrt7$\no*: $5$\no: $4$\nwhy: في الزائد $c^2=a^2+b^2=9+16=25$ . (الطرح $\\sqrt7$ للناقص.)\n>>> horient .enr\np: في القطع نفسه، أين تقع البؤرتان؟\nask: اختر:\no: على محور السينات لأن $16>9$\no*: على محور الصادات لأن حد $y^2$ موجب\no: لا يمكن التحديد\nwhy: في الزائد الحد **الموجب** يحدد المحور الحقيقي، لا المقام الأكبر.\n>>> horient .summary\nh2: الخلاصة\n- $|PF_1-PF_2|=2a$ ، و $c^2=a^2+b^2$ ، و $e=\\tfrac ca>1$ .\n- الحد الموجب يحدد محور البؤرتين: $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1$ أو $\\dfrac{y^2}{a^2}-\\dfrac{x^2}{b^2}=1$ .\n- الرسم: مستطيل $2a\\times2b$ وقطراه هما المستقيمان المحاذيان.\n- القطع الزائد القائم: $a=b$ و $e=\\sqrt2$ .\n\n=== htrans | 2−7 | انسحاب محاور القطع الزائد | 86–89 | المركز (h , k) : (x − h)²/a² − (y − k)²/b² = 1 أو (y − k)²/a² − (x − h)²/b² = 1 ، والبؤرتان والرأسان تنسحب مع المركز.\n--- @discover اكتشف: الزائد حول مركز جديد\n>>> htrans .act\nk: [2−7] · انسحاب محاور القطع الزائد\nh1: المركز ينتقل، والشكل لا يتغير\nlead: كما في المكافئ والناقص: عندما ينتقل المركز إلى $\\cf{(h , k)}$ تبقى $a , b , c$ كما هي، وينسحب كل شيء معه.\np: **حرّك الانسحاب** أو **اسحب المركز** إلى أي موضع لترى كل حالات h و k ، والمعادلة تتغير معه. هذا قطع المثال 22 ، ومركزه $(-2,1)$ .\n>>>\nask: في القطع $\\dfrac{(x-3)^2}{a^2}-\\dfrac{(y+4)^2}{b^2}=1$ ، المحور الحقيقي هو المستقيم:\no: $x=3$\no*: $y=-4$\no: $y=4$\nwhy: الحد الموجب فيه $x$ ، فالمحور الحقيقي أفقي ويمر بالمركز $(3,-4)$ : معادلته $y=k=-4$ .\n--- @understand افهم: المعادلتان بعد الانسحاب\n>>> htrans .book\nk: [2−7−1] · ص 86\nh2: معادلة القطع الزائد الذي مركزه النقطة (h , k) ومحوراه يوازيان المحورين المتعامدين\np: **اولاً :** عند انسحاب مركز القطع الزائد بمقدار $(h)$ من الوحدات على محور السينات وبمقدار $(k)$ من الوحدات على محور الصادات والمحور الحقيقي يوازي محور السينات تصبح المعادلة .\nlaw:\n| $$\\frac{(x-h)^2}{a^2}-\\frac{(y-k)^2}{b^2}=1\n| حيث المحور الحقيقي يوازي محور السينات\n| والبؤرتان هما $\\overline{F_1}(c+h,k)\\ ,\\ \\overline{F_2}(-c+h,k)$\n| والرأسان هما $\\overline{V_1}(a+h,k)\\ ,\\ \\overline{V_2}(-a+h,k)$\n>>> htrans .book\nk: ص 87\np: **ثانياً :** يمكن الحصول على معادلة القطع الزائد الذي محوره الحقيقي يوازي محور الصادات ومركزه نقطة $(h,k)$ . في هذه الحالة تكون المعادلة للقطع الزائد هي : وكما في الشكل (2−29)\nlaw:\n| $$\\frac{(y-k)^2}{a^2}-\\frac{(x-h)^2}{b^2}=1\n| البؤرتان هما $\\overline{F_1}(h,c+k)\\ ,\\ \\overline{F_2}(h,-c+k)$\n| والرأسان هما $\\overline{V_1}(h,a+k)\\ ,\\ \\overline{V_2}(h,-a+k)$\nnote: سنقتصر في البند [2−7] على ايجاد مركز القطع الزائد وبؤرتاه ورأساه وطول المحورين .\n--- @learn تعلّم الحل: المركز، ثم c² = a² + b²\n>>> htrans .book\nk: فكرة الحل في هذا الدرس\nh2: نحسب كأن المركز في الأصل ثم نزيح\nxp: فكرة الحل في هذا الدرس\n| **1) نكمل المربعين** إن لزم، ونجعل الطرف الأيمن $1$ .\n| **2) المركز** $(h,k)$ بإشارة معاكسة لما داخل القوسين.\n| **3) الحد الموجب** يحدد المحور الحقيقي، و $a^2$ مقامه، و $c^2=a^2+b^2$ .\n| **4) نضيف** $\\pm a$ و $\\pm c$ إلى إحداثي المركز على اتجاه المحور الحقيقي.\n| **فحص:** المركز منتصف البؤرتين، و $e>1$ .\n>>> htrans .book\nk: مثال 22 · ص 88\nh2: المحور الحقيقي يوازي محور السينات\np: جد احداثيا المركز والبؤرتين والرأسين وطول المحورين والاختلاف المركزي للقطع الزائد الذي معادلته :\n$$\\frac{(x+2)^2}{9}-\\frac{(y-1)^2}{4}=1\nlet: المعطيات\n| المعادلة ; المعطاة ; $\\dfrac{(x+2)^2}{9}-\\dfrac{(y-1)^2}{4}=1$\n| الحد الموجب ; فيه $x$ ; المحور الحقيقي يوازي محور السينات\n| المطلوب ; العناصر والاختلاف المركزي ; $e$\nmain: [المعادلة القياسية] المحور الحقيقي يوازي محور السينات\n| $$\\frac{(x-h)^2}{a^2}-\\frac{(y-k)^2}{b^2}=1\n>>> htrans #1 :: المحوران والمركز\np: **الحل:** بمقارنة هذه المعادلة بالمعادلة القياسية نجد :\n$$\\Rightarrow a^2=9\\Rightarrow a=3\\Rightarrow2a=6\np: طول المحور الحقيقي ، وحدة\n$$\\Rightarrow b^2=4\\Rightarrow b=2\\Rightarrow2b=4\np: طول المحور المرافق ، وحدة\n$$\\Rightarrow h=-2\\ ,\\quad k=1\np: المركز $\\therefore\\ (h,k)=(-2,1)$\n>>> htrans #2 :: c والبؤرتان\n$$c^2=a^2+b^2\\Rightarrow c^2=9+4=13\\Rightarrow c=\\sqrt{13}\np: لان المحور الحقيقي يوازي محور السينات $\\therefore\\ \\overline{F_1}(c+h,k)\\ ,\\ \\overline{F_2}(-c+h,k)$\np: البؤرتان\n$$\\Rightarrow\\overline{F_1}(\\sqrt{13}-2,1)\\ ,\\ \\overline{F_2}(-\\sqrt{13}-2,1)\n>>> htrans ! #3 :: الرأسان و e\n$$\\overline{V_1}(a+h,k)\\ ,\\ \\overline{V_2}(-a+h,k)\np: الرأسان\n$$\\overline{V_1}(1,1)\\ ,\\ \\overline{V_2}(-5,1)\n$$\\therefore\\ e=\\frac ca=\\frac{\\sqrt{13}}{3}>1\np: (الاختلاف المركزي)\nxp: فحص\n| المركز $(-2,1)$ منتصف الرأسين: $\\tfrac{1+(-5)}{2}=-2$ ✓\n| $\\sqrt{13}\\approx3.6>3$ ، فـ $e>1$ ✓\n--- @practice تدرّب: تمارين ص 89 (مركز ليس في نقطة الأصل)\n>>> htrans .book\nk: تمارين · 1 · ص 89\nh2: دورك الآن\np: **1.** عين كل من البؤرتين والرأسين ثم جد طول كل من المحورين والاختلاف المركزي للقطوع الزائدة الاتية : **c)** $2(y+1)^2-4(x-1)^2=8$\nxp: قالب الحل\n| **1)** نجعل الطرف الأيمن $1$ .\n| **2)** المركز $(h,k)$ .\n| **3)** الحد الموجب يحدد المحور، ومقامه $a^2$ .\n| **4)** $c^2=a^2+b^2$ ، ثم نضيف $\\pm a$ و $\\pm c$ إلى المركز.\n| **فحص:** $e>1$ .\nself:\nhint: اقسم على 8 .\nsol: **الحل:**\n| let> المعادلة ; بعد القسمة على 8 ; $\\dfrac{(y+1)^2}{4}-\\dfrac{(x-1)^2}{2}=1$\n| main> [المعادلة القياسية] المحور الحقيقي يوازي محور الصادات\n| $$c=\\sqrt{4+2}=\\sqrt6\n| المركز $(1,-1)$\n| البؤرتان $(1\\ ,\\ -1\\pm\\sqrt6)$\n| الرأسان $(1,1)\\ ,\\ (1,-3)$\n| المحور الحقيقي $4$\n| المحور المرافق $2\\sqrt2$\n| $e=\\dfrac{\\sqrt6}{2}$\n>>> htrans .book\np: **d)** $16x^2+160x-9y^2+18y=185$\nself:\nhint: $16(x^2+10x+25)-9(y^2-2y+1)=185+400-9$\nsol: **الحل:**\n| let> المعادلة ; بعد إكمال المربعين ; $\\dfrac{(x+5)^2}{36}-\\dfrac{(y-1)^2}{64}=1$\n| main> [المعادلة القياسية] المحور الحقيقي يوازي محور السينات\n| $$c=\\sqrt{36+64}=10\n| المركز $(-5,1)$\n| البؤرتان $(5,1)\\ ,\\ (-15,1)$\n| الرأسان $(1,1)\\ ,\\ (-11,1)$\n| المحور الحقيقي $12$\n| المحور المرافق $16$\n| $e=\\dfrac{10}{6}=\\dfrac53$\n--- @check تحقّق\n>>> htrans .enr\nk: تقويم قصير · ليس من الكتاب\np: ما بؤرتا القطع $\\dfrac{(y-2)^2}{16}-\\dfrac{x^2}{9}=1$ ؟\nask: اختر:\no: $(\\pm5,2)$\no*: $(0,7)\\ ,\\ (0,-3)$\no: $(0,2\\pm\\sqrt7)$\nwhy: المركز $(0,2)$ والمحور الحقيقي عمودي، و $c=\\sqrt{16+9}=5$ ⇐ $(0,2\\pm5)$ .\n>>> htrans .enr\np: أي العبارات صحيحة لكل قطع زائد؟\nask: اختر:\no: $a>b$ دائماً\no*: $c>a$ دائماً\no: $c<b$ دائماً\nwhy: $c^2=a^2+b^2$ ، فـ $c$ أكبر من $a$ ومن $b$ ؛ أما $a$ و $b$ فأيهما يمكن أن يكون الأكبر.\n>>> htrans .summary\nh2: الخلاصة\n- المركز $(h,k)$ : $\\dfrac{(x-h)^2}{a^2}-\\dfrac{(y-k)^2}{b^2}=1$ (حقيقي أفقي) أو $\\dfrac{(y-k)^2}{a^2}-\\dfrac{(x-h)^2}{b^2}=1$ (حقيقي عمودي).\n- $c^2=a^2+b^2$ ، والبؤرتان والرأسان على المحور الحقيقي حول المركز.\n- القطوع الثلاثة: المكافئ $e=1$ ، الناقص $e<1$ ، الزائد $e>1$ .\n"});
})();
